// Sound lab S4 Recorder.  uv run pio run -d labs/sound-lab-s4 -e sound-lab-s4 -t upload
// A voice-activated recorder. Armed, it waits for sound louder than the trigger, then records,
// starting half a second *before* the trigger (the pre-roll: the sampler's ring still has it),
// until 1.2 s of quiet. Clips go to PSRAM (12 clips, 6 MB, gone on reset). Listen to them on your
// phone at http://bench.local (the Wi-Fi W1 saved, plus the admin token), or pull a WAV file over
// USB with tools/sound_pull.py.
//
// And with the MAX98357A + speaker wired, `play <n>` plays a clip on the board itself, at any speed
// (0.5 = slower and deeper, 2 = the chipmunk).
//
// Which microphone matters here more than anywhere. The KY-037 has no amplifier, so a voice fills
// a small part of the ADC's range: clips are made louder ("normalised") on the way out and sound
// thin and hissy: a loudness sensor first, a microphone second. The INMP441 has its own amplifier
// and a 24-bit converter inside: its clips are actually pleasant to listen to. `mic auto` (the
// default) picks the INMP441 whenever it answers.
//
// Echo guard: while the speaker plays (and 200 ms after), the shell gives the lab no frames, so the
// voice trigger can't record the board's own playback. `play` refuses while recording, and `rec`
// stops a playback first.
//
// Wiring: a microphone (KY-037: + -> 3V3, G -> GND, AO -> GPIO 6, DO -> GPIO 21; or INMP441: VDD ->
// 3V3, GND, L/R -> GND, SCK -> 40, WS -> 41, SD -> 42), the screen from lesson 03, optionally the
// MAX98357A (VIN -> 5V, GND, BCLK -> 39, LRC -> 38, DIN -> 47). Push button on GPIO 5 optional.
//
// Views: recorder · clips · web   (click = next, double-click = the action in the footer,
//        long press = rec / stop; on the clips view: double-click = play, long press = next clip)
// Serial: help lists the commands. Shared code: kit/lib/sound-kit, kit/lib/wifi-kit (Wi-Fi, token).
#include "api_token.h"
#include "connection.h"
#include "recorder.h"
#include "recorder_api.h"
#include "s4_views.h"
#include "sound_lab.h"

namespace {

rec::Recorder recorder;
ApiToken token;
Connection connection;
RecorderApi api(recorder.store(), token);
int picked = 0;          // the clips view's picked row
uint32_t lastStatus = 0;

// Playback on the board's speaker. The clip is leased from the store while it plays, so `del`,
// `clear` or a full store can take it off the list but can't free its samples under the speaker.
// The speaker task reads the samples on its own core, up to a block (16 ms) after it was told to
// stop, so a stopped clip is "retiring" for 100 ms before its lease is given back.
struct Playback {
  rec::Clip *clip = nullptr;
  uint32_t number = 0;
  float speed = 1;
  uint32_t sinceMs = 0;
} playback;
rec::Clip *retiring = nullptr;
uint32_t retireAt = 0;

void endPlayback() {
  rec::ClipStore::release(retiring);  // an older one still retiring: long done by now
  retiring = playback.clip;
  retireAt = millis();
  playback = Playback{};
}

// ---- Views ------------------------------------------------------------------------------------

void drawRecorder(SoundLab &, FrameBuffer &fb, float t) { s4v::recorder(fb, recorder, recorder.config(), recorder.store(), t); }
void drawClips(SoundLab &lab, FrameBuffer &fb, float) {
  s4v::clips(fb, recorder.store(), picked, playback.number, playback.clip ? lab.speaker().progress() : 0);
}
void drawWeb(SoundLab &, FrameBuffer &fb, float) { s4v::web(fb, connection, api.started(), api.clients()); }

const SoundView kViews[] = {
    {"recorder", drawRecorder, "arm"},
    {"clips", drawClips, "play"},
    {"web", drawWeb, "wifi"},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdArm(SoundLab &lab, const String &, const String &lower) {
  if (!lower.isEmpty() && lower != "on" && lower != "off") return lab.warn("arm | arm on | arm off");
  recorder.arm(lab, lower.isEmpty() ? !recorder.armed() : lower == "on");
}

void stopPlayback(SoundLab &lab) {
  if (!playback.clip) return;
  lab.speaker().stop();
  lab.note(sv::Note::Info, "playback of clip %lu stopped", static_cast<unsigned long>(playback.number));
  endPlayback();
}

void cmdRec(SoundLab &lab, const String &, const String &) {
  if (recorder.recording()) return recorder.stop(lab);  // rec again (or a long press) stops
  stopPlayback(lab);  // never record the board's own speaker
  recorder.start(lab);
}

void cmdStop(SoundLab &lab, const String &, const String &) {
  if (playback.clip && !recorder.recording()) return stopPlayback(lab);
  recorder.stop(lab);
}

// Play clip n (0 = the picked one) at `speed` on the board's speaker.
void startPlayback(SoundLab &lab, uint32_t n, float speed) {
  if (recorder.recording()) return lab.warn("recording: stop first (the microphone would hear the speaker)");
  if (n == 0) {
    rec::Clip c;
    if (!recorder.store().facts(picked, c)) return lab.warn("no clips yet");
    n = c.number;
  }
  rec::Clip *c = recorder.store().lease(n);
  if (!c) return lab.warn("no finished clip %lu", static_cast<unsigned long>(n));
  if (playback.clip) {
    lab.speaker().stop();
    endPlayback();
  }
  // Normalised like the download, but at most x16: a whisper on the KY-037 would otherwise come
  // back as mostly hiss, at full volume.
  const float gain = std::min(16.0f, snd::gainFor(c->peak));
  playback = Playback{c, n, speed, millis()};
  lab.speaker().play(c->data, c->samples, speed * float(c->rate) / float(snd::Speaker::kRate), gain);
  lab.note(sv::Note::Good, "playing clip %lu (%.1f s) at x%.2f", static_cast<unsigned long>(n), c->durationMs() / 1000.0f / speed, speed);
}

void cmdPlay(SoundLab &lab, const String &arg, const String &) {
  const int sp = arg.indexOf(' ');
  long n = 0;
  float speed = 1.0f;
  if (!arg.isEmpty() && !SoundLab::number(sp < 0 ? arg : arg.substring(0, sp), 1, 1000000, n))
    return lab.warn("play [n] [speed 0.5-2.0]: clip n (default: the picked one) on the board's speaker");
  if (sp > 0 && !SoundLab::decimal(arg.substring(sp + 1), 0.5f, 2.0f, speed)) return lab.warn("speed: 0.5 (slow, deep) to 2.0 (fast, chipmunk)");
  startPlayback(lab, uint32_t(n), speed);
}

void cmdTrigger(SoundLab &lab, const String &arg, const String &) {
  float db = 0;
  if (!SoundLab::decimal(arg, 3, 60, db)) return lab.warn("trigger <dB above the quiet>, 3-60 (now %.0f)", recorder.config().startDb);
  recorder.config().startDb = db;
  lab.note(sv::Note::Info, "voice starts above %.0f dB", db);
}

void cmdHold(SoundLab &lab, const String &arg, const String &) {
  long ms = 0;
  if (!SoundLab::number(arg, 200, 10000, ms)) return lab.warn("hold <ms>, 200-10000: quiet this long ends a clip (now %lu)", static_cast<unsigned long>(recorder.config().holdMs));
  recorder.config().holdMs = uint32_t(ms);
  lab.note(sv::Note::Info, "a clip ends after %.1f s of quiet", ms / 1000.0f);
}

void cmdMax(SoundLab &lab, const String &arg, const String &) {
  long s = 0;
  if (!SoundLab::number(arg, 1, 120, s)) return lab.warn("max <s>, 1-120: the longest clip (now %lu)", static_cast<unsigned long>(recorder.config().maxMs / 1000));
  recorder.config().maxMs = uint32_t(s) * 1000;
  lab.note(sv::Note::Info, "clips stop at %ld s (from the next one)", s);
}

void cmdClips(SoundLab &lab, const String &, const String &) {
  rec::ClipStore &store = recorder.store();
  Serial.printf("%d clips, %.2f of %.0f MB of PSRAM (gone on reset):\n", store.count(), store.used() / 1048576.0, store.budget / 1048576.0);
  Serial.println("    #  length  kind   loudest     sent x  started");
  store.each([](const rec::Clip &c) {
    char when[24] = "-";
    if (c.wall > 0) {
      const time_t w = time_t(c.wall);
      struct tm tm;
      localtime_r(&w, &tm);
      strftime(when, sizeof(when), "%Y-%m-%d %H:%M:%S", &tm);
    }
    Serial.printf("  %3lu  %5.1fs  %-5s  %5.1f dBFS  x%-5.1f %s%s\n", static_cast<unsigned long>(c.number), c.durationMs() / 1000.0f,
                  c.manual ? "hand" : "voice", snd::toDb(float(c.peak)), snd::gainFor(c.peak), when, c.open ? "  (recording)" : "");
  });
  lab.showView("clips");
}

void cmdNext(SoundLab &lab, const String &, const String &) {
  const int n = recorder.store().count();
  picked = n ? (picked + 1) % n : 0;
  lab.showView("clips");
}

void cmdDel(SoundLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!SoundLab::number(arg, 1, 1000000, n)) return lab.warn("del <n>: the clip's number (clips lists them)");
  if (recorder.recording() && uint32_t(n) == recorder.clipNumber()) return lab.warn("clip %ld is recording: stop first", n);
  if (!recorder.store().remove(uint32_t(n))) return lab.warn("no clip %ld", n);
  lab.note(sv::Note::Info, "clip %ld deleted", n);
}

void cmdClear(SoundLab &lab, const String &, const String &) {
  const int n = recorder.store().clear();
  picked = 0;
  lab.note(sv::Note::Info, "%d clip%s deleted", n, n == 1 ? "" : "s");
}

// The serial transfer: a header line, the WAV file as base64 lines, a CRC-32 line. Nothing else may
// be printed in between, so this runs to the end before loop() goes on (~20 s for 5 s of sound
// at 115200 baud: 32 KB of WAV a second of sound, 4/3 more as base64, 11.5 KB/s down the wire).
void cmdSend(SoundLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!SoundLab::number(arg, 1, 1000000, n)) return lab.warn("send <n>: for tools/sound_pull.py (close the serial monitor first)");
  if (recorder.recording()) return lab.warn("recording: stop first, the transfer pauses everything else");
  rec::Clip *c = recorder.store().lease(uint32_t(n));
  if (!c) return lab.warn("no finished clip %ld", n);
  const float gain = snd::gainFor(c->peak);
  char name[48];
  rec::clipName(*c, name, sizeof(name));
  const size_t total = c->wavBytes();
  Serial.printf("WAV-BEGIN %lu %u %s\n", static_cast<unsigned long>(c->number), unsigned(total), name);
  uint8_t bytes[57];  // 57 bytes = one 76-character base64 line
  char line[80];
  uint32_t crc = 0;
  for (size_t at = 0; at < total;) {
    const size_t got = rec::wavRead(*c, gain, bytes, sizeof(bytes), at);
    crc = rec::crc32(crc, bytes, got);
    rec::base64(bytes, got, line);
    Serial.println(line);
    at += got;
  }
  Serial.printf("WAV-END %08lx\n", static_cast<unsigned long>(crc));
  rec::ClipStore::release(c);
  lab.note(sv::Note::Good, "sent clip %ld (%u bytes)", n, unsigned(total));
}

void cmdToken(SoundLab &lab, const String &, const String &lower) {
  if (lower == "new") {
    token.regenerate();
    lab.note(sv::Note::Warn, "new admin token: open pages must unlock again");
  } else if (!lower.isEmpty()) {
    return lab.warn("token | token new");
  }
  Serial.printf("Admin token: %s\nPaste it into the page at http://%s.local (it is shared with R7/R8; keep it out of chats and git)\n",
                token.value().c_str(), Connection::kHostname);
}

void cmdWifi(SoundLab &lab, const String &, const String &) {
  if (connection.ssid().isEmpty()) return lab.warn("no Wi-Fi saved: flash wifi-lab-w1 once and join, or use tools/sound_pull.py over USB");
  if (connection.state() != Connection::State::Connected)
    return lab.note(sv::Note::Warn, "joining '%s'... (last reason: %s)", connection.ssid().c_str(), Connection::reasonHint(connection.lastReason()));
  Serial.printf("Wi-Fi '%s' · IP %s · %ld dBm · page http://%s.local · %u page(s) open\n", connection.ssid().c_str(),
                WiFi.localIP().toString().c_str(), static_cast<long>(WiFi.RSSI()), Connection::kHostname, unsigned(api.clients()));
  lab.showView("web");
}

const SoundCommand kCommands[] = {
    {"arm", "[on|off]", "voice-activated recording (alone: toggle)", cmdArm},
    {"rec", "", "record now, by hand (again, or long press: stop)", cmdRec},
    {"stop", "", "stop recording (or the board's playback)", cmdStop},
    {"play", "[n] [speed]", "play clip n on the board's speaker, speed 0.5-2.0 (default 1)", cmdPlay},
    {"trigger", "<dB>", "how loud starts a clip, dB above the quiet (default 15)", cmdTrigger},
    {"hold", "<ms>", "quiet this long ends a clip (default 1200)", cmdHold},
    {"max", "<s>", "the longest clip (default 20)", cmdMax},
    {"clips", "", "list the clips (PSRAM only: gone on reset)", cmdClips},
    {"next", "", "pick the next clip on the clips view", cmdNext},
    {"del", "<n>", "delete clip n", cmdDel},
    {"clear", "", "delete every finished clip", cmdClear},
    {"send", "<n>", "clip n as a WAV over serial, for tools/sound_pull.py", cmdSend},
    {"token", "[new]", "the admin token the phone page asks for", cmdToken},
    {"wifi", "", "Wi-Fi and the page's address", cmdWifi},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(SoundLab &lab) {
  token.begin();
  connection.begin();
  Serial.println("S4: clips are kept in PSRAM only, a reset forgets them. Recording always shows: REC on screen, red LED.");
  if (!lab.mic().digital())
    Serial.println("S4: recording with the KY-037: expect thin, hissy clips. An INMP441 (mic auto) sounds far better.");
}

void frame(SoundLab &lab, const snd::Frame &f, uint32_t ms) { recorder.frame(lab, f, ms); }

void publishStatus(SoundLab &lab) {
  const snd::LevelReading &r = lab.level();
  const rec::ClipStore &store = recorder.store();
  JsonDocument d;
  d["state"] = recorder.recording() ? "recording" : recorder.armed() ? "armed" : "off";
  d["armed"] = recorder.armed();
  d["manual"] = recorder.recording() && recorder.manual();
  d["clip"] = recorder.clipNumber();
  d["recMs"] = recorder.recordedMs();
  d["above"] = roundf(r.above() * 10) / 10;
  d["floorDb"] = roundf(r.floorDb * 10) / 10;
  d["trigger"] = recorder.config().startDb;
  d["holdMs"] = recorder.config().holdMs;
  d["maxS"] = recorder.config().maxMs / 1000;
  d["prerollMs"] = recorder.config().prerollMs;
  d["clips"] = store.count();
  d["usedBytes"] = store.used();
  d["budgetBytes"] = store.budget;
  d["rate"] = lab.mic().rate();
  d["mic"] = snd::sourceShort(lab.mic().source());
  d["playing"] = playback.number;  // 0 = the board's speaker is quiet
  d["playProgress"] = playback.clip ? roundf(lab.speaker().progress() * 1000) / 1000 : 0;
  String out;
  serializeJson(d, out);
  api.publishStatus(out);
}

void tick(SoundLab &lab) {
  // Playback ends when the speaker says so; then the clip goes back to the store.
  // (Give the speaker task 150 ms to pick up the play command before trusting "not playing".)
  if (playback.clip && !lab.speaker().playing() && millis() - playback.sinceMs > 150) {
    lab.note(sv::Note::Info, "clip %lu played", static_cast<unsigned long>(playback.number));
    endPlayback();
  }
  if (retiring && millis() - retireAt > 100) {
    rec::ClipStore::release(retiring);
    retiring = nullptr;
  }
  recorder.tick(lab);
  connection.loop();
  if (!api.started() && connection.state() == Connection::State::Connected) {
    api.begin();
    lab.note(sv::Note::Good, "page: http://%s.local", Connection::kHostname);
  }
  if (!api.started()) return;
  WebCommand c;
  while (api.take(c)) {
    switch (c.type) {
      case WebCommand::Type::Arm: recorder.arm(lab, c.value != 0); break;
      case WebCommand::Type::Rec:
        stopPlayback(lab);
        recorder.start(lab);
        break;
      case WebCommand::Type::Stop:
        if (recorder.recording()) recorder.stop(lab);
        stopPlayback(lab);
        break;
      case WebCommand::Type::Play: startPlayback(lab, c.value, c.speed); break;
      case WebCommand::Type::Delete:
        if (recorder.recording() && c.value == recorder.clipNumber()) lab.note(sv::Note::Warn, "web: clip %lu is recording", static_cast<unsigned long>(c.value));
        else if (recorder.store().remove(c.value)) lab.note(sv::Note::Info, "web: clip %lu deleted", static_cast<unsigned long>(c.value));
        break;
    }
  }
  api.loop();
  if (millis() - lastStatus >= 100) {
    lastStatus = millis();
    publishStatus(lab);
  }
}

// On the clips view, a long press picks the next clip (double-click plays it). Elsewhere: rec.
bool gesture(SoundLab &lab, Gesture g, bool) {
  if (g != Gesture::LongPress || strcmp(lab.spec().views[lab.view()].name, "clips") != 0) return false;
  Serial.println("> next   (long press)");
  lab.runLine("next");
  return true;
}

const SoundLabSpec kSpec{
    "sound-lab-s4", "S4", "Recorder", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, frame, tick, gesture, "rec",
};

SoundLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// The recorder: snd::Trigger decides when, this copies the sound into clips.
//
// The sampler never stops and never waits for us: it keeps writing the last 4 s into its ring.
// The recorder only remembers a sample number, `cursor_`, and every frame copies everything from
// there up to the newest sample into the open clip. That is why a recording can start 500 ms in
// the past (the pre-roll is still in the ring), and why a slow screen frame loses nothing. Only if
// loop() fell more than ~4 s behind would the ring have overwritten what we hadn't copied yet:
// then the clip ends early, and says so.
//
// The envelope: for the recorder view, the last 3 s of frames as "dB above the quiet" plus what
// each frame became (nothing, pre-roll, recorded).
#pragma once

#include <esp_heap_caps.h>
#include <time.h>

#include "clips.h"
#include "sound_lab.h"
#include "trigger.h"

namespace rec {

inline void *psramAlloc(size_t n) { return heap_caps_malloc(n, MALLOC_CAP_SPIRAM); }
inline void *psramResize(void *p, size_t n) { return heap_caps_realloc(p, n, MALLOC_CAP_SPIRAM); }
inline void psramFree(void *p) { heap_caps_free(p); }

// "s4-clip-3-20261014-213005.wav", or "s4-clip-3.wav" when the clock wasn't set.
inline void clipName(const Clip &c, char *out, size_t n) {
  if (c.wall <= 0) {
    snprintf(out, n, "s4-clip-%lu.wav", static_cast<unsigned long>(c.number));
    return;
  }
  const time_t t = time_t(c.wall);
  struct tm tm;
  localtime_r(&t, &tm);
  char when[20];
  strftime(when, sizeof(when), "%Y%m%d-%H%M%S", &tm);
  snprintf(out, n, "s4-clip-%lu-%s.wav", static_cast<unsigned long>(c.number), when);
}

class Recorder {
 public:
  static constexpr int kEnvelope = 750;  // frames: 3 s at 4 ms
  enum Mark : uint8_t { None, PreRoll, Recorded };

  Recorder() : store_(Allocator{psramAlloc, psramResize, psramFree}), trigger_(16000) {}

  ClipStore &store() { return store_; }
  snd::TriggerConfig &config() { return trigger_.config; }
  snd::Trigger::State state() const { return trigger_.state(); }
  bool armed() const { return trigger_.armed(); }
  bool recording() const { return clip_ != nullptr; }
  bool manual() const { return trigger_.manual(); }
  uint32_t clipNumber() const { return clip_ ? clip_->number : 0; }
  uint32_t recordedMs() const { return clip_ ? clip_->durationMs() : 0; }

  // ---- The envelope, for the screen ------------------------------------------------------------

  int envelopeHead() const { return head_; }
  uint8_t envelopeDb(int i) const { return db_[(head_ + i) % kEnvelope]; }  // 0 = oldest
  Mark envelopeMark(int i) const { return Mark(mark_[(head_ + i) % kEnvelope]); }

  // ---- From the lab's hooks --------------------------------------------------------------------

  void frame(SoundLab &lab, const snd::Frame &f, uint32_t ms) {
    const float above = lab.level().above();
    db_[head_] = uint8_t(std::min(255.0f, lab.level().instAbove()));
    mark_[head_] = clip_ ? Recorded : None;
    head_ = (head_ + 1) % kEnvelope;
    // A frame more than a second old means loop() was stuck (a serial `send`, say): don't let it
    // start a recording of sound that may already be gone from the ring.
    if (lab.mic().written() - f.end > lab.mic().rate()) return;
    trigger_.setRate(lab.mic().rate());
    handle(lab, trigger_.push(above, f.end), ms);
  }

  void tick(SoundLab &lab) {
    pump(lab, lab.mic().written());
    store_.collect();
    lab.setRecording(clip_ != nullptr);  // the REC dot and the red LED: nothing records without them
  }

  // ---- Commands --------------------------------------------------------------------------------

  void arm(SoundLab &lab, bool on) {
    trigger_.arm(on);
    lab.note(sv::Note::Info, on ? "armed: talk and it records" : "voice trigger off");
  }

  void start(SoundLab &lab) {
    if (clip_) return lab.note(sv::Note::Info, "already recording clip %lu", static_cast<unsigned long>(clip_->number));
    trigger_.setRate(lab.mic().rate());
    handle(lab, trigger_.start(lab.mic().written()), lab.soundMs());
  }

  void stop(SoundLab &lab) {
    if (!clip_) return lab.note(sv::Note::Info, "not recording");
    handle(lab, trigger_.stop(lab.mic().written()), lab.soundMs());
  }

 private:
  uint32_t samples(uint32_t ms, uint32_t rate) const { return uint32_t(uint64_t(ms) * rate / 1000); }

  void handle(SoundLab &lab, const snd::Trigger::Result &r, uint32_t ms) {
    using A = snd::Trigger::Action;
    const uint32_t rate = lab.mic().rate();
    if (r.action == A::Start) {
      const uint32_t pre = trigger_.config.prerollMs;
      const time_t now = time(nullptr);
      const int64_t wall = now > 1'700'000'000 ? int64_t(now) - pre / 1000 : 0;
      // Room for the longest clip, plus a few frames: the trigger checks the length once per frame.
      const uint32_t capacity = samples(trigger_.config.maxMs, rate) + 4 * snd::kChunk;
      const ClipStore::Opened o = store_.open(rate, capacity, trigger_.manual(), ms > pre ? ms - pre : 0, wall);
      if (!o.clip) {
        // Back to off: left armed, a loud room would retry (and fail) 250 times a second.
        trigger_.stop(r.from);
        const bool wasArmed = trigger_.armed();
        trigger_.arm(false);
        return lab.note(sv::Note::Bad, "can't record: %s%s", o.why, wasArmed ? " (voice trigger off)" : "");
      }
      if (o.dropped) lab.note(sv::Note::Warn, "store full: dropped the %d oldest voice clip%s", o.dropped, o.dropped > 1 ? "s" : "");
      clip_ = o.clip;
      cursor_ = r.from;
      // Paint the pre-roll into the envelope: those frames are in the clip after all.
      const int back = std::min<int>(kEnvelope, int((r.to - r.from) / snd::kChunk));
      for (int i = 1; i <= back; i++) mark_[(head_ - i + kEnvelope) % kEnvelope] = PreRoll;
      lab.note(sv::Note::Bad, "REC clip %lu (%s)", static_cast<unsigned long>(clip_->number), clip_->manual ? "by hand" : "voice");
      lab.setRecording(true);
    } else if (r.action == A::Save || r.action == A::Drop) {
      if (!clip_) return;
      pump(lab, r.to);
      finish(lab, r.action == A::Save, nullptr);
    }
  }

  void finish(SoundLab &lab, bool keep, const char *why) {
    Clip *c = clip_;
    clip_ = nullptr;
    lab.setRecording(false);
    const uint32_t number = c->number, ms = c->durationMs();
    store_.close(c, keep);
    if (!keep) return lab.note(sv::Note::Info, "a bang, not a voice: clip %lu dropped", static_cast<unsigned long>(number));
    lab.note(why ? sv::Note::Warn : sv::Note::Good, "clip %lu: %.1f s%s%s", static_cast<unsigned long>(number), ms / 1000.0f, why ? ", " : "",
             why ? why : "");
  }

  // Copy from the cursor up to sample number `upTo` into the open clip.
  void pump(SoundLab &lab, uint32_t upTo) {
    static int16_t buf[1024];
    while (clip_ && cursor_ < upTo) {
      const uint32_t n = std::min<uint32_t>(1024, upTo - cursor_);
      if (!lab.mic().copy(cursor_, buf, n)) {
        trigger_.stop(cursor_);
        return finish(lab, true, "ended early: loop fell 4 s behind");
      }
      store_.append(clip_, buf, n);
      cursor_ += n;
      if (store_.full(clip_)) {
        trigger_.stop(cursor_);
        return finish(lab, true, "the longest clip (max)");
      }
    }
  }

  ClipStore store_;
  snd::Trigger trigger_;
  Clip *clip_ = nullptr;
  uint32_t cursor_ = 0;
  uint8_t db_[kEnvelope] = {}, mark_[kEnvelope] = {};
  int head_ = 0;
};

}  // namespace rec

// S4's web side: the phone page at http://bench.local/, a JSON API and a WebSocket on port 80
// (the same libraries as W2, R7 and R8).
//
// Privacy first. A microphone you can reach over Wi-Fi is a bug in a box, so:
//   - every /api route (except the index) and the WebSocket need the admin token: the same one R7
//     and R8 use, kept in NVS, printed only by the serial command `token`. The page asks for it
//     once and keeps it in the tab's sessionStorage (gone when the tab closes);
//   - the board shows every recording, whoever started it: the REC dot, the red LED, the big REC;
//   - clips live in RAM only and vanish on reset.
//
// Endpoints:
//   GET    /                  the page (no audio in it: it fetches clips with the token)
//   GET    /api               this list
//   GET    /api/status        state, level, settings, store use
//   GET    /api/clips         the clips (facts, not sound)
//   GET    /api/clip?n=N      clip N as a WAV file, normalised (&raw=1: the numbers as recorded)
//   DELETE /api/clip?n=N      delete clip N
//   POST   /api/arm?on=1|0    voice trigger on or off
//   POST   /api/rec           start recording now
//   POST   /api/stop          stop recording, and stop the board's playback
//   POST   /api/play?n=N      play clip N on the board's speaker (&speed=0.5-2.0, default 1)
//   WS     /ws?token=...      pushes {"type": "status" | "clips", "data": ...}, ~10 a second
//
// Web requests run in the network task; loop() owns the recorder. So the API never changes the
// recorder itself: it queues a WebCommand and loop() applies it (W2's commands.h pattern). Reading
// a clip is the exception that's safe: the clip is leased, so a delete can't free it mid-download.
#pragma once

#include <ArduinoJson.h>
#include <ESPAsyncWebServer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

#include <memory>
#include <mutex>

#include "api_token.h"
#include "clips.h"
#include "recorder.h"
#include "web_page.h"

struct WebCommand {
  enum class Type : uint8_t { Arm, Rec, Stop, Delete, Play };
  Type type;
  uint32_t value = 0;  // Arm: 1/0 · Delete, Play: the clip number
  float speed = 1.0f;  // Play: 0.5-2.0
};

class RecorderApi {
 public:
  RecorderApi(rec::ClipStore &store, const ApiToken &token) : store_(store), token_(token) {}

  void begin() {
    queue_ = xQueueCreate(8, sizeof(WebCommand));
    ws_.onEvent([this](AsyncWebSocket *, AsyncWebSocketClient *client, AwsEventType type, void *arg, uint8_t *, size_t) {
      if (type != WS_EVT_CONNECT) return;
      // The browser can't add headers to a WebSocket, so the token comes in the URL: /ws?token=...
      auto *req = static_cast<AsyncWebServerRequest *>(arg);
      if (!req || !req->hasParam("token") || !token_.allows("Bearer " + req->getParam("token")->value())) {
        client->close(4001, "token");
        return;
      }
      std::lock_guard<std::mutex> lock(mutex_);  // the latest picture straight away
      if (!status_.isEmpty()) client->text(wrap("status", status_));
      client->text(wrap("clips", clipsJson()));
    });
    server_.addHandler(&ws_);

    server_.on(AsyncURIMatcher::exact("/"), HTTP_GET, [](AsyncWebServerRequest *req) {
      AsyncWebServerResponse *res = req->beginResponse(200, "text/html", reinterpret_cast<const uint8_t *>(kPage), strlen(kPage));
      res->addHeader("Cache-Control", "no-store");
      req->send(res);
    });
    server_.on(AsyncURIMatcher::exact("/api"), HTTP_GET, [](AsyncWebServerRequest *req) { req->send(200, "application/json", kIndex); });
    server_.on(AsyncURIMatcher::exact("/api/status"), HTTP_GET, [this](AsyncWebServerRequest *req) {
      if (!admin(req)) return;
      std::lock_guard<std::mutex> lock(mutex_);
      if (status_.isEmpty()) return error(req, 503, "starting up");
      req->send(200, "application/json", status_);
    });
    server_.on(AsyncURIMatcher::exact("/api/clips"), HTTP_GET, [this](AsyncWebServerRequest *req) {
      if (!admin(req)) return;
      req->send(200, "application/json", clipsJson());
    });
    server_.on(AsyncURIMatcher::exact("/api/clip"), HTTP_GET, [this](AsyncWebServerRequest *req) { download(req); });
    server_.on(AsyncURIMatcher::exact("/api/clip"), HTTP_DELETE, [this](AsyncWebServerRequest *req) {
      uint32_t n = 0;
      if (!admin(req) || !clipParam(req, n)) return;
      queue(req, {WebCommand::Type::Delete, n});
    });
    server_.on(AsyncURIMatcher::exact("/api/arm"), HTTP_POST, [this](AsyncWebServerRequest *req) {
      if (!admin(req)) return;
      if (!req->hasParam("on")) return error(req, 400, "on: 1 or 0, e.g. /api/arm?on=1");
      queue(req, {WebCommand::Type::Arm, req->getParam("on")->value() == "1" ? 1u : 0u});
    });
    server_.on(AsyncURIMatcher::exact("/api/rec"), HTTP_POST, [this](AsyncWebServerRequest *req) {
      if (admin(req)) queue(req, {WebCommand::Type::Rec, 0});
    });
    server_.on(AsyncURIMatcher::exact("/api/stop"), HTTP_POST, [this](AsyncWebServerRequest *req) {
      if (admin(req)) queue(req, {WebCommand::Type::Stop, 0});
    });
    server_.on(AsyncURIMatcher::exact("/api/play"), HTTP_POST, [this](AsyncWebServerRequest *req) {
      uint32_t n = 0;
      if (!admin(req) || !clipParam(req, n)) return;
      float speed = 1.0f;
      if (req->hasParam("speed")) {
        speed = req->getParam("speed")->value().toFloat();
        if (speed < 0.5f || speed > 2.0f) return error(req, 400, "speed: 0.5 to 2.0");
      }
      queue(req, {WebCommand::Type::Play, n, speed});
    });
    server_.onNotFound([](AsyncWebServerRequest *req) { error(req, 404, "no such endpoint, see /api"); });
    server_.begin();
    started_ = true;
    log_i("Web server on port 80: the page at /, the API at /api, live updates at /ws");
  }

  bool started() const { return started_; }
  size_t clients() const { return started_ ? ws_.count() : 0; }

  // ---- From loop() ------------------------------------------------------------------------------

  bool take(WebCommand &c) { return queue_ && xQueueReceive(queue_, &c, 0) == pdTRUE; }

  void publishStatus(const String &json) {
    {
      std::lock_guard<std::mutex> lock(mutex_);
      status_ = json;
    }
    if (ws_.count()) ws_.textAll(wrap("status", json));
  }

  void loop() {
    const uint32_t now = millis();
    if (now - lastCleanup_ > 2000) lastCleanup_ = now, ws_.cleanupClients();
    const uint32_t v = store_.version();
    if (v != clipsVersion_) {
      clipsVersion_ = v;
      if (ws_.count()) ws_.textAll(wrap("clips", clipsJson()));
    }
  }

 private:
  // A lease that gives the clip back when the response that holds it is destroyed, however the
  // download ends (finished, cancelled, connection lost).
  struct Lease {
    rec::Clip *clip;
    ~Lease() { rec::ClipStore::release(clip); }
  };

  void download(AsyncWebServerRequest *req) {
    uint32_t n = 0;
    if (!admin(req) || !clipParam(req, n)) return;
    rec::Clip *c = store_.lease(n);
    if (!c) return error(req, 404, "no finished clip with this number (see /api/clips)");
    auto lease = std::make_shared<Lease>(Lease{c});
    const bool raw = req->hasParam("raw") && req->getParam("raw")->value() == "1";
    const float gain = raw ? 1.0f : snd::gainFor(c->peak);
    // The WAV is never built in memory: the network asks for the next few hundred bytes, we make them.
    AsyncWebServerResponse *res = req->beginResponse("audio/wav", c->wavBytes(), [lease, gain](uint8_t *buf, size_t maxLen, size_t index) -> size_t {
      return rec::wavRead(*lease->clip, gain, buf, maxLen, index);
    });
    char name[48], disposition[80];
    rec::clipName(*c, name, sizeof(name));
    snprintf(disposition, sizeof(disposition), "inline; filename=\"%s\"", name);
    res->addHeader("Content-Disposition", disposition);
    res->addHeader("Cache-Control", "no-store");
    req->send(res);
  }

  String clipsJson() {
    JsonDocument d;
    JsonArray a = d.to<JsonArray>();
    store_.each([&](const rec::Clip &c) {
      JsonObject o = a.add<JsonObject>();
      char name[48];
      rec::clipName(c, name, sizeof(name));
      o["n"] = c.number;
      o["name"] = static_cast<const char *>(name);  // copied: name is a local buffer
      o["ms"] = c.durationMs();
      o["rate"] = c.rate;
      o["bytes"] = c.wavBytes();
      o["peakDb"] = roundf(snd::toDb(float(c.peak)) * 10) / 10;
      o["gain"] = roundf(snd::gainFor(c.peak) * 10) / 10;
      o["manual"] = c.manual;
      o["open"] = c.open;
      o["wall"] = c.wall;  // Unix seconds, 0 = unknown
    });
    String out;
    serializeJson(d, out);
    return out;
  }

  void queue(AsyncWebServerRequest *req, const WebCommand &c) {
    if (!queue_ || xQueueSend(queue_, &c, 0) != pdTRUE) return error(req, 503, "busy, try again");
    req->send(202, "application/json", "{\"ok\":true}");
  }

  bool admin(AsyncWebServerRequest *req) {
    if (req->hasHeader("Authorization") && token_.allows(req->header("Authorization"))) return true;
    error(req, 401, "send Authorization: Bearer <token> (serial command: token)");
    return false;
  }

  static bool clipParam(AsyncWebServerRequest *req, uint32_t &n) {
    if (req->hasParam("n")) {
      const long v = req->getParam("n")->value().toInt();
      if (v > 0) return n = uint32_t(v), true;
    }
    error(req, 400, "n: the clip number, e.g. ?n=3");
    return false;
  }

  static void error(AsyncWebServerRequest *req, int code, const char *message) {
    JsonDocument d;
    d["error"] = message;
    String out;
    serializeJson(d, out);
    req->send(code, "application/json", out);
  }

  static String wrap(const char *type, const String &data) { return String("{\"type\":\"") + type + "\",\"data\":" + data + "}"; }

  static constexpr const char *kIndex =
      "{\"endpoints\":[\"GET / (the page)\",\"GET /api/status\",\"GET /api/clips\",\"GET /api/clip?n=N[&raw=1]\",\"DELETE /api/clip?n=N\","
      "\"POST /api/arm?on=1|0\",\"POST /api/rec\",\"POST /api/stop\",\"POST /api/play?n=N[&speed=1.0]\",\"WS /ws?token=...\"],"
      "\"auth\":\"everything but this list: Authorization: Bearer <token> (serial command: token)\"}";

  rec::ClipStore &store_;
  const ApiToken &token_;
  AsyncWebServer server_{80};
  AsyncWebSocket ws_{"/ws"};
  QueueHandle_t queue_ = nullptr;
  std::mutex mutex_;
  String status_;
  bool started_ = false;
  uint32_t lastCleanup_ = 0, clipsVersion_ = 0xFFFFFFFF;
};

// S4's three screens (320 x 170, under the shared header):
//   recorder  the state as a big word (OFF, ARMED, REC 3.2 s), the last 3 s of loudness with the
//             trigger line, the pre-roll (amber) and what went into a clip (red)
//   clips     the list with each clip's shape, and the picked clip's facts; a playhead runs
//             across the clip the speaker is playing
//   web       where the page is, the Wi-Fi, how to get the token, who is watching
#pragma once

#include <WiFi.h>

#include "connection.h"
#include "recorder.h"
#include "sound_views.h"

namespace s4v {

using sv::kTop;

inline void recorder(FrameBuffer &fb, const rec::Recorder &r, const snd::TriggerConfig &cfg, const rec::ClipStore &store, float t) {
  // The state, big: nobody should wonder whether this thing is listening.
  char word[24];
  uint16_t c = pal::muted;
  if (r.recording()) {
    snprintf(word, sizeof(word), "REC %.1f s", r.recordedMs() / 1000.0f);
    c = sv::kRec;
    if (fmodf(t, 1.0f) < 0.6f) fb.fillCircle(16, kTop + 26, 8, sv::kRec);
  } else if (r.armed()) {
    snprintf(word, sizeof(word), "ARMED");
    c = pal::teal;
    fb.drawCircle(16, kTop + 26, 8, pal::teal);
  } else {
    snprintf(word, sizeof(word), "OFF");
    fb.drawCircle(16, kTop + 26, 8, pal::dim);
  }
  sv::big(fb, 32, kTop + 42, c, word);

  char line[40];
  snprintf(line, sizeof(line), "%d clips", store.count());
  sv::small(fb, 236, kTop + 12, pal::ink, line);
  snprintf(line, sizeof(line), "%.1f / %.0f MB", store.used() / 1048576.0f, store.budget / 1048576.0f);
  sv::small(fb, 236, kTop + 24, pal::muted, line);
  sv::small(fb, 236, kTop + 36, pal::muted, "lost on reset");

  // The last 3 s, newest on the right: each column the loudest of ~2.5 frames, mirrored.
  const int x = 10, y = kTop + 54, w = 300, h = 66, mid = y + h / 2;
  fb.fillRect(x, y, w, h, sv::kPanel);
  constexpr float kRange = 50;  // dB above the quiet across the half-height
  for (int col = 0; col < w; col++) {
    const int a = col * rec::Recorder::kEnvelope / w, b = (col + 1) * rec::Recorder::kEnvelope / w;
    int db = 0;
    rec::Recorder::Mark mark = rec::Recorder::None;
    for (int i = a; i < b; i++) {
      db = std::max<int>(db, r.envelopeDb(i));
      mark = std::max(mark, r.envelopeMark(i));
    }
    const int half = std::min(h / 2 - 1, int(db / kRange * (h / 2)));
    const uint16_t colour = mark == rec::Recorder::Recorded ? sv::kRec : mark == rec::Recorder::PreRoll ? pal::amber : sv::kSound;
    if (mark != rec::Recorder::None) fb.drawFastVLine(x + col, y, h, mix(colour, sv::kPanel, 200));
    if (half > 0) fb.drawFastVLine(x + col, mid - half, half * 2 + 1, colour);
  }
  // The trigger: louder than this line starts a recording (when armed).
  const int ty = std::min(h / 2 - 1, int(cfg.startDb / kRange * (h / 2)));
  for (int i = x; i < x + w; i += 4) fb.drawPixel(i, mid - ty, pal::ink), fb.drawPixel(i, mid + ty, pal::ink);
  sv::small(fb, x + 2, y + 2, pal::muted, "3 s ago");
  sv::small(fb, x + w - 20, y + 2, pal::muted, "now");
  // (The screen's built-in font has no "·": plain ASCII only on the display.)
  char settings[64];
  snprintf(settings, sizeof(settings), "start %.0f dB, hold %.1f s, pre-roll %.1f s", cfg.startDb, cfg.holdMs / 1000.0f, cfg.prerollMs / 1000.0f);
  sv::small(fb, x, y + h + 4, pal::muted, settings);
}

inline void clips(FrameBuffer &fb, const rec::ClipStore &store, int &picked, uint32_t playing = 0, float progress = 0) {
  const int n = store.count();
  if (n == 0) {
    sv::bold(fb, 12, kTop + 34, pal::ink, "No clips yet.");
    sv::small(fb, 12, kTop + 52, pal::muted, "arm (voice trigger) or rec (by hand), then talk.");
    sv::small(fb, 12, kTop + 66, pal::muted, "Clips live in PSRAM: a reset forgets them.");
    return;
  }
  picked = std::min(std::max(picked, 0), n - 1);
  // Four rows, scrolled so the picked one is visible. Newest at the bottom.
  const int first = std::max(0, std::min(picked - 1, n - 4));
  for (int row = 0; row < 4 && first + row < n; row++) {
    rec::Clip c;
    if (!store.facts(first + row, c)) break;
    const int y = kTop + 4 + row * 30;
    const bool on = first + row == picked;
    if (on) fb.fillRoundRect(4, y, 178, 27, 4, sv::kPanel);
    char num[8];
    snprintf(num, sizeof(num), "%lu", static_cast<unsigned long>(c.number));
    sv::bold(fb, 10, y + 19, on ? sv::kSound : pal::ink, num);
    // The clip's shape from its 48-slice overview, mirrored.
    for (int b = 0; b < 48; b++) {
      const int half = c.open ? 1 : std::max(1, c.overview[b] * 11 / 255);
      fb.drawFastVLine(42 + b * 2, y + 13 - half, half * 2, c.open ? sv::kRec : on ? sv::kSound : pal::muted);
    }
    char dur[12];
    snprintf(dur, sizeof(dur), "%.1fs", c.durationMs() / 1000.0f);
    sv::small(fb, 142, y + 6, pal::ink, dur);
    const bool sounding = playing && c.number == playing;
    sv::small(fb, 142, y + 16, sounding ? pal::teal : pal::muted, c.open ? "REC" : sounding ? "PLAY" : c.manual ? "hand" : "voice");
    if (sounding) {
      // The playhead: what the speaker has played so far, over the clip's shape.
      const int px = 42 + int(std::min(1.0f, progress) * 96);
      fb.drawFastVLine(px, y + 1, 25, pal::ink);
      fb.fillTriangle(px - 3, y + 1, px + 3, y + 1, px, y + 5, pal::ink);
    }
  }
  // The picked clip's facts.
  rec::Clip c;
  if (!store.facts(picked, c)) return;
  char a[24], b[24];
  snprintf(a, sizeof(a), "%.1f dBFS", snd::toDb(float(c.peak)));
  snprintf(b, sizeof(b), "x%.1f", snd::gainFor(c.peak));
  sv::stat(fb, 194, kTop + 4, "loudest", a);
  sv::stat(fb, 194, kTop + 42, "sent louder by", b, sv::kSound);
  if (c.wall > 0) {
    const time_t w = time_t(c.wall);
    struct tm tm;
    localtime_r(&w, &tm);
    strftime(a, sizeof(a), "%H:%M:%S", &tm);
  } else {
    snprintf(a, sizeof(a), "%lus in", static_cast<unsigned long>(c.startMs / 1000));
  }
  sv::stat(fb, 194, kTop + 80, "started", a);
  snprintf(b, sizeof(b), "long press: next clip");
  sv::small(fb, 194, kTop + 118, pal::muted, b);
}

inline void web(FrameBuffer &fb, const Connection &conn, bool apiUp, size_t clients) {
  const bool joined = conn.state() == Connection::State::Connected;
  if (conn.ssid().isEmpty()) {
    sv::bold(fb, 12, kTop + 26, pal::amber, "No Wi-Fi saved");
    sv::small(fb, 12, kTop + 44, pal::muted, "Run W1 once to join your network,");
    sv::small(fb, 12, kTop + 56, pal::muted, "or pull clips over USB:");
    sv::small(fb, 12, kTop + 72, pal::ink, "tools/sound_pull.py <port> <n>");
    return;
  }
  char a[40];
  if (joined) snprintf(a, sizeof(a), "http://%s.local", Connection::kHostname);
  else snprintf(a, sizeof(a), "joining %s...", conn.ssid().c_str());
  sv::bold(fb, 12, kTop + 22, joined ? sv::kSound : pal::amber, a);
  if (joined) {
    char ip[24], rssi[16], who[16];
    snprintf(ip, sizeof(ip), "%s", WiFi.localIP().toString().c_str());
    snprintf(rssi, sizeof(rssi), "%ld dBm", static_cast<long>(WiFi.RSSI()));
    snprintf(who, sizeof(who), "%u", unsigned(clients));
    sv::stat(fb, 12, kTop + 34, "or", ip);
    sv::stat(fb, 150, kTop + 34, "signal", rssi);
    sv::stat(fb, 240, kTop + 34, "pages open", who, clients ? pal::teal : pal::ink);
  }
  sv::small(fb, 12, kTop + 78, pal::muted, apiUp ? "The page asks for the admin token:" : "The page starts once Wi-Fi is up.");
  sv::small(fb, 12, kTop + 90, pal::ink, "type token in the serial monitor.");
  sv::small(fb, 12, kTop + 106, pal::muted, "Recording always shows here: REC + red LED.");
}

}  // namespace s4v

// S4's clip store: the recordings, kept in PSRAM (8 MB of RAM outside the chip; it forgets
// everything on reset or power-off: nothing here is written to flash).
//
// Each clip is plain 16-bit samples at the mic's rate, the same numbers the sampler put in its
// ring. While recording, a clip has room for the longest allowed recording; when it ends, the
// buffer is shrunk to what was actually recorded, so short clips cost little.
//
// Limits: 12 clips and a 6 MB budget. When a new recording doesn't fit, the oldest
// voice-activated clips go first; clips you started by hand (rec) are never dropped for you.
//
// Two tasks use the store: loop() records and deletes; the web server's task streams clips out.
// A download can take seconds, so a clip being sent is "leased": deleting it only takes it off
// the list, and the memory is freed by collect() once the last download has finished with it.
//
// Clip numbers count up from 1 and are never reused, so "del 3" always means the clip shown as 3.
// Pure C++ (no Arduino): host-tested in labs/sound-lab-s4/test/host/sound_clips_test.cpp.
#pragma once

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include <atomic>
#include <mutex>

#include "wav.h"

namespace rec {

struct Clip {
  uint32_t number = 0;
  uint32_t rate = 16000;
  uint32_t samples = 0;   // recorded so far
  uint32_t capacity = 0;  // room for this many
  uint32_t startMs = 0;   // on the lab's sound clock
  int64_t wall = 0;       // Unix time when it started, 0 = the clock wasn't set (no NTP yet)
  int16_t *data = nullptr;
  int peak = 0;           // the biggest |sample|
  bool manual = false;    // started by hand (rec) rather than by the voice trigger
  bool open = true;       // still recording
  uint8_t overview[48] = {};  // the clip's shape for the screen: 48 slices, each its loudest |sample|, 0-255
  std::atomic<int> readers{0};

  uint32_t durationMs() const { return rate ? uint32_t(uint64_t(samples) * 1000 / rate) : 0; }
  uint32_t wavBytes() const { return snd::kWavHeader + samples * 2; }
};

// Where clip memory comes from: PSRAM on the board, malloc in the host test.
struct Allocator {
  void *(*alloc)(size_t);
  void *(*resize)(void *, size_t);
  void (*release)(void *);
};

class ClipStore {
 public:
  static constexpr int kMax = 12;
  static constexpr int kGrave = 12;
  size_t budget = 6u * 1024 * 1024;

  explicit ClipStore(Allocator a) : mem_(a) {}

  struct Opened {
    Clip *clip = nullptr;
    int dropped = 0;          // old voice clips removed to make room
    const char *why = "";     // when clip is nullptr
  };

  // Start a clip with room for `capacity` samples. Drops the oldest voice clips if needed.
  Opened open(uint32_t rate, uint32_t capacity, bool manual, uint32_t startMs, int64_t wall) {
    Opened o;
    const size_t bytes = size_t(capacity) * 2;
    std::lock_guard<std::mutex> lock(mutex_);
    if (bytes > budget) return o.why = "longer than the whole store", o;
    while (count_ >= kMax || usedLocked() + bytes > budget) {
      const int i = oldestVoiceLocked();
      if (i < 0) return o.why = count_ >= kMax ? "12 clips kept: del or clear some" : "store full: del or clear some", o;
      removeAtLocked(i);
      o.dropped++;
    }
    Clip *c = new Clip;
    c->data = static_cast<int16_t *>(mem_.alloc(bytes));
    if (!c->data) {
      delete c;
      return o.why = "no PSRAM left", o;
    }
    c->number = ++lastNumber_;
    c->rate = rate, c->capacity = capacity, c->startMs = startMs, c->wall = wall, c->manual = manual;
    clips_[count_++] = c;
    version_++;
    o.clip = c;
    return o;
  }

  // Add samples to an open clip (loop() only). Returns how many fitted.
  uint32_t append(Clip *c, const int16_t *s, uint32_t n) {
    if (!c || !c->open) return 0;
    if (n > c->capacity - c->samples) n = c->capacity - c->samples;
    for (uint32_t i = 0; i < n; i++) {
      const int a = s[i] < 0 ? -int(s[i]) : s[i];
      if (a > c->peak) c->peak = a;
    }
    memcpy(c->data + c->samples, s, n * 2);
    c->samples += n;
    return n;
  }
  bool full(const Clip *c) const { return c && c->samples >= c->capacity; }

  // End a clip: keep it (shrunk to size) or throw it away.
  void close(Clip *c, bool keep) {
    if (!c) return;
    if (!keep || c->samples == 0) {
      remove(c->number);
      return;
    }
    std::lock_guard<std::mutex> lock(mutex_);
    if (c->samples < c->capacity) {
      void *smaller = mem_.resize(c->data, size_t(c->samples) * 2);
      if (smaller) c->data = static_cast<int16_t *>(smaller), c->capacity = c->samples;
    }
    // The overview: the loudest sample in each of 48 slices, relative to the whole clip's peak.
    for (int b = 0; b < 48; b++) {
      const uint32_t from = uint64_t(c->samples) * b / 48, to = uint64_t(c->samples) * (b + 1) / 48;
      int m = 0;
      for (uint32_t i = from; i < to; i++) {
        const int a = c->data[i] < 0 ? -int(c->data[i]) : c->data[i];
        if (a > m) m = a;
      }
      c->overview[b] = uint8_t(c->peak ? m * 255 / c->peak : 0);
    }
    c->open = false;
    version_++;
  }

  bool remove(uint32_t number) {
    std::lock_guard<std::mutex> lock(mutex_);
    for (int i = 0; i < count_; i++)
      if (clips_[i]->number == number) return removeAtLocked(i), true;
    return false;
  }

  // Remove every finished clip (an open one keeps recording).
  int clear() {
    std::lock_guard<std::mutex> lock(mutex_);
    int removed = 0;
    for (int i = count_ - 1; i >= 0; i--)
      if (!clips_[i]->open) removeAtLocked(i), removed++;
    return removed;
  }

  // Lease a finished clip for reading from another task. nullptr if there is no such clip.
  Clip *lease(uint32_t number) {
    std::lock_guard<std::mutex> lock(mutex_);
    for (int i = 0; i < count_; i++)
      if (clips_[i]->number == number && !clips_[i]->open) return clips_[i]->readers++, clips_[i];
    return nullptr;
  }
  static void release(Clip *c) {
    if (c) c->readers--;
  }

  // Free deleted clips nobody reads any more (loop() calls this every frame).
  void collect() {
    std::lock_guard<std::mutex> lock(mutex_);
    for (int i = graveCount_ - 1; i >= 0; i--)
      if (grave_[i]->readers.load() == 0) {
        freeClip(grave_[i]);
        grave_[i] = grave_[--graveCount_];
      }
  }

  // Look at the list under the lock: f(const Clip &) for each, oldest first.
  template <typename F>
  void each(F f) const {
    std::lock_guard<std::mutex> lock(mutex_);
    for (int i = 0; i < count_; i++) f(*clips_[i]);
  }
  // A copy of clip i's facts (not its samples), for drawing. False when i is past the end.
  bool facts(int i, Clip &out) const {
    std::lock_guard<std::mutex> lock(mutex_);
    if (i < 0 || i >= count_) return false;
    const Clip &c = *clips_[i];
    out.number = c.number, out.rate = c.rate, out.samples = c.samples, out.capacity = c.capacity, out.startMs = c.startMs;
    out.wall = c.wall, out.data = c.data, out.peak = c.peak, out.manual = c.manual, out.open = c.open;
    memcpy(out.overview, c.overview, sizeof(out.overview));
    return true;
  }

  int count() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return count_;
  }
  size_t used() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return usedLocked();
  }
  uint32_t version() const { return version_.load(); }  // changes whenever the list does

 private:
  size_t usedLocked() const {
    size_t n = 0;
    for (int i = 0; i < count_; i++) n += size_t(clips_[i]->capacity) * 2;
    for (int i = 0; i < graveCount_; i++) n += size_t(grave_[i]->capacity) * 2;
    return n;
  }

  int oldestVoiceLocked() const {
    for (int i = 0; i < count_; i++)
      if (!clips_[i]->manual && !clips_[i]->open) return i;
    return -1;
  }

  void removeAtLocked(int i) {
    Clip *c = clips_[i];
    for (int j = i; j + 1 < count_; j++) clips_[j] = clips_[j + 1];
    count_--;
    version_++;
    if (c->readers.load() == 0 || graveCount_ >= kGrave) freeClip(c);  // a full grave: free anyway (never happens in practice)
    else grave_[graveCount_++] = c;
  }

  void freeClip(Clip *c) {
    mem_.release(c->data);
    delete c;
  }

  Allocator mem_;
  mutable std::mutex mutex_;
  Clip *clips_[kMax] = {};
  Clip *grave_[kGrave] = {};
  int count_ = 0, graveCount_ = 0;
  uint32_t lastNumber_ = 0;
  std::atomic<uint32_t> version_{0};
};

// ---- Reading a clip as a WAV file ----------------------------------------------------------------

// Copy up to maxLen bytes of the clip's WAV file, starting at byte `index`, with `gain` applied
// (snd::gainFor(peak) to normalise, 1 for the raw numbers). Returns the bytes written, 0 at the end.
// Used by both the web download (in pieces, as the network asks) and the serial `send`.
inline size_t wavRead(const Clip &c, float gain, uint8_t *buf, size_t maxLen, size_t index) {
  const size_t total = c.wavBytes();
  if (index >= total) return 0;
  size_t n = 0;
  if (index < size_t(snd::kWavHeader)) {
    uint8_t h[snd::kWavHeader];
    snd::wavHeader(h, c.rate, c.samples);
    while (index < size_t(snd::kWavHeader) && n < maxLen) buf[n++] = h[index++];
  }
  while (index < total && n < maxLen) {
    const size_t at = index - snd::kWavHeader;
    const int16_t s = snd::applyGain(c.data[at / 2], gain);
    buf[n++] = (at & 1) ? uint8_t(uint16_t(s) >> 8) : uint8_t(s);  // little-endian: low byte first
    index++;
  }
  return n;
}

// ---- The serial transfer: base64 lines + a CRC-32 ------------------------------------------------

// Base64: every 3 bytes become 4 printable characters, so binary survives a text-only serial line.
inline size_t base64(const uint8_t *in, size_t n, char *out) {
  static const char kAbc[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  size_t o = 0;
  for (size_t i = 0; i < n; i += 3) {
    const uint32_t v = uint32_t(in[i]) << 16 | (i + 1 < n ? uint32_t(in[i + 1]) << 8 : 0) | (i + 2 < n ? in[i + 2] : 0);
    out[o++] = kAbc[(v >> 18) & 63];
    out[o++] = kAbc[(v >> 12) & 63];
    out[o++] = i + 1 < n ? kAbc[(v >> 6) & 63] : '=';
    out[o++] = i + 2 < n ? kAbc[v & 63] : '=';
  }
  out[o] = 0;
  return o;
}

// CRC-32 (the one zip, PNG and Python's zlib.crc32 use): start with crc = 0, feed every byte.
inline uint32_t crc32(uint32_t crc, const uint8_t *p, size_t n) {
  crc = ~crc;
  for (size_t i = 0; i < n; i++) {
    crc ^= p[i];
    for (int b = 0; b < 8; b++) crc = (crc >> 1) ^ (0xEDB88320u & (0u - (crc & 1)));
  }
  return ~crc;
}

}  // namespace rec

