<script>
"use strict";
const $ = (s, root = document) => root.querySelector(s);
const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
let token = sessionStorage.getItem("s4-token") || "";
let ws = null, retry = null, last = null;
let ctx = null, playing = null;  // { n, src, startedAt, offset }
const clips = new Map();         // n -> { el, buffer, url, info }

for (let i = 0; i < 30; i++) $("#meter").append(document.createElement("i"));
const trig = document.createElement("span");
trig.className = "trig"; trig.setAttribute("aria-hidden", "true");
$("#meter").append(trig);

function lock(message) {
  token = ""; sessionStorage.removeItem("s4-token");
  if (ws) { ws.onclose = null; ws.close(); ws = null; }
  $("#unlock").hidden = false; $("#deck").hidden = true; $("#clips-card").hidden = true;
  $("#unlock-error").textContent = message || "";
  $("#link").textContent = "locked";
  for (const c of clips.values()) URL.revokeObjectURL(c.url);
  clips.clear(); $("#clips").replaceChildren();
}

async function api(path, method = "GET") {
  const r = await fetch(path, { method, headers: { Authorization: "Bearer " + token } });
  if (r.status === 401) { lock("That token didn't work. Type token in the serial monitor for the current one."); throw new Error("locked"); }
  if (!r.ok) throw new Error((await r.json().catch(() => ({}))).error || r.statusText);
  return r;
}

function connect() {
  clearTimeout(retry);
  $("#link").textContent = "connecting...";
  ws = new WebSocket(`ws://${location.host}/ws?token=${encodeURIComponent(token)}`);
  ws.onopen = () => { $("#unlock").hidden = true; $("#deck").hidden = false; $("#clips-card").hidden = false; $("#link").textContent = "live"; };
  ws.onmessage = (e) => {
    const m = JSON.parse(e.data);
    if (m.type === "status") showStatus(m.data);
    if (m.type === "clips") showClips(m.data);
  };
  ws.onclose = (e) => {
    if (e.code === 4001) return lock("That token didn't work. Type token in the serial monitor for the current one.");
    $("#link").textContent = "reconnecting...";
    retry = setTimeout(connect, 2000);
  };
}

function showStatus(s) {
  last = s;
  const st = $("#state");
  st.dataset.state = s.state;
  $("#state-text").textContent = s.state === "recording" ? "REC" : s.state.toUpperCase();
  $("#state-more").textContent = s.state === "recording" ? `clip ${s.clip} · ${(s.recMs / 1000).toFixed(1)} s${s.manual ? " · by hand" : ""}`
    : s.armed ? `starts at ${s.trigger} dB above the quiet` : "press Record, or turn on the voice trigger";
  const lit = Math.round(Math.min(1, s.above / 60) * 30);
  [...$("#meter").children].forEach((el, i) => {
    if (el.tagName !== "I") return;
    el.className = i < lit ? `on${i >= 20 ? " hot" : i >= 12 ? " loud" : ""}` : "";
  });
  $("#meter").setAttribute("aria-valuenow", String(Math.round(s.above)));
  trig.style.left = `${Math.min(1, s.trigger / 60) * 100}%`;
  $("#arm").setAttribute("aria-pressed", String(s.armed));
  $("#mic").textContent = `S4 · ${s.mic}`;
  for (const [n, entry] of clips) {
    const on = s.playing === n, bar = $(".board-progress", entry.el);
    bar.hidden = !on;
    if (on) bar.value = s.playProgress;
    $(".board", entry.el).textContent = on ? "Stop on board" : "Play on board";
    $(".board", entry.el).disabled = entry.info.open || s.state === "recording";
  }
  $("#rec").disabled = s.state === "recording";
  $("#stop").disabled = s.state !== "recording";
  $("#facts").replaceChildren(...[
    `${s.clips} clip${s.clips === 1 ? "" : "s"} · ${(s.usedBytes / 1048576).toFixed(1)} of ${(s.budgetBytes / 1048576).toFixed(0)} MB`,
    `hold ${(s.holdMs / 1000).toFixed(1)} s · max ${s.maxS} s · pre-roll ${(s.prerollMs / 1000).toFixed(1)} s`,
    `${(s.rate / 1000).toFixed(0)} kHz · quiet at ${s.floorDb.toFixed(0)} dBFS`,
  ].map((t) => Object.assign(document.createElement("span"), { textContent: t })));
}

function when(c) {
  if (!c.wall) return "";
  return new Date(c.wall * 1000).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

function showClips(list) {
  const seen = new Set();
  for (const c of list) {
    seen.add(c.n);
    let entry = clips.get(c.n);
    if (!entry) {
      const el = $("#clip-tpl").content.firstElementChild.cloneNode(true);
      entry = { el, buffer: null, url: null, info: c, loading: false };
      clips.set(c.n, entry);
      $(".play", el).onclick = () => toggle(c.n);
      $(".delete", el).onclick = () => remove(c.n);
      $(".board", el).onclick = () => command(last && last.playing === c.n ? "/api/stop" : `/api/play?n=${c.n}&speed=${$("#speed").value}`);
      $("canvas", el).onclick = (e) => {
        const r = e.currentTarget.getBoundingClientRect();
        play(c.n, ((e.clientX - r.left) / r.width) * (entry.buffer ? entry.buffer.duration : 0));
      };
      $("#clips").prepend(el);
    }
    entry.info = c;
    $("h3", entry.el).textContent = `Clip ${c.n}${c.open ? " · recording" : ""}`;
    $(".when", entry.el).textContent = when(c);
    $(".info", entry.el).textContent = `${(c.ms / 1000).toFixed(1)} s · ${c.manual ? "by hand" : "voice"} · x${c.gain} louder`;
    $(".download", entry.el).download = c.name;
    for (const b of entry.el.querySelectorAll("button, a")) b.toggleAttribute("disabled", c.open);
    if (!c.open && !entry.buffer && !entry.loading) load(c.n);
  }
  for (const [n, entry] of clips) if (!seen.has(n)) { if (playing && playing.n === n) stop(); URL.revokeObjectURL(entry.url); entry.el.remove(); clips.delete(n); }
  $("#empty").hidden = list.length > 0;
}

async function load(n) {
  const entry = clips.get(n);
  entry.loading = true;
  try {
    const blob = await (await api(`/api/clip?n=${n}`)).blob();
    entry.url = URL.createObjectURL(blob);
    $(".download", entry.el).href = entry.url;
    ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
    entry.buffer = await ctx.decodeAudioData(await blob.arrayBuffer());
    draw(n, 0);
  } catch (err) {
    $(".info", entry.el).textContent = `could not load: ${err.message}`;
  } finally { entry.loading = false; }
}

// The waveform: for each pixel column, the lowest and highest sample that falls in it.
function draw(n, position) {
  const entry = clips.get(n);
  if (!entry || !entry.buffer) return;
  const canvas = $("canvas", entry.el), dpr = window.devicePixelRatio || 1;
  const w = Math.max(1, Math.round(canvas.clientWidth * dpr)), h = Math.round(canvas.clientHeight * dpr);
  if (canvas.width !== w) canvas.width = w;
  if (canvas.height !== h) canvas.height = h;
  const g = canvas.getContext("2d"), data = entry.buffer.getChannelData(0), per = data.length / w;
  const playedTo = (position / entry.buffer.duration) * w;
  g.clearRect(0, 0, w, h);
  for (let x = 0; x < w; x++) {
    let lo = 1, hi = -1;
    for (let i = Math.floor(x * per), end = Math.floor((x + 1) * per); i < end; i++) { const v = data[i]; if (v < lo) lo = v; if (v > hi) hi = v; }
    if (hi < lo) continue;
    g.fillStyle = x < playedTo ? css("--wave-played") : css("--wave");
    g.fillRect(x, ((1 - hi) / 2) * h, 1, Math.max(1, ((hi - lo) / 2) * h));
  }
  if (position > 0) { g.fillStyle = css("--playhead"); g.fillRect(Math.round(playedTo), 0, Math.max(1, dpr), h); }
}

function play(n, offset = 0) {
  const entry = clips.get(n);
  if (!entry || !entry.buffer) return;
  stop();
  ctx.resume();
  const src = ctx.createBufferSource();
  src.buffer = entry.buffer;
  src.connect(ctx.destination);
  src.start(0, Math.max(0, Math.min(offset, entry.buffer.duration - 0.01)));
  playing = { n, src, startedAt: ctx.currentTime - offset };
  src.onended = () => { if (playing && playing.src === src) stop(); };
  $(".play", entry.el).textContent = "Pause";
  const frame = () => {
    if (!playing || playing.src !== src) return;
    draw(n, ctx.currentTime - playing.startedAt);
    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);
}

function stop() {
  if (!playing) return;
  const { n, src } = playing;
  playing = null;
  try { src.stop(); } catch (e) { /* already ended */ }
  const entry = clips.get(n);
  if (entry) { $(".play", entry.el).textContent = "Play"; draw(n, 0); }
}

function toggle(n) { if (playing && playing.n === n) stop(); else play(n); }

async function remove(n) {
  if (!confirm(`Delete clip ${n}? It is only on the board, so it's gone for good.`)) return;
  try { await api(`/api/clip?n=${n}`, "DELETE"); } catch (err) { if (err.message !== "locked") alert(err.message); }
}

async function command(path) {
  try { await api(path, "POST"); } catch (err) { if (err.message !== "locked") $("#state-more").textContent = err.message; }
}

$("#arm").onclick = () => command(`/api/arm?on=${last && last.armed ? 0 : 1}`);
$("#rec").onclick = () => command("/api/rec");
$("#stop").onclick = () => command("/api/stop");
$("#unlock").onsubmit = (e) => {
  e.preventDefault();
  token = $("#token").value.trim();
  sessionStorage.setItem("s4-token", token);
  $("#token").value = "";
  connect();
};
window.addEventListener("resize", () => { for (const n of clips.keys()) if (!playing || playing.n !== n) draw(n, 0); });
if (token) connect();
</script>
</body>
</html>
)HTML";

// The admin token: a random secret that guards the actions that could change the bench (W2:
// firmware update, forgetting the Wi-Fi network, rebooting; R7: every change to the card list).
//
// It is created on first boot from the chip's hardware random number generator and kept in NVS
// (namespace "api", so every lab on this board shares it). It is printed over serial with the
// `token` command, never sent by the API. The Mac side keeps a copy in a git-ignored .env file
// and adds it to admin requests as "Authorization: Bearer <token>". `token new` makes a fresh one.
#pragma once

#include <Arduino.h>
#include <Preferences.h>
#include <esp_random.h>

class ApiToken {
 public:
  void begin() {
    Preferences prefs;
    prefs.begin("api", true);
    token_ = prefs.getString("token", "");
    prefs.end();
    if (token_.length() != 32) regenerate();
  }

  void regenerate() {
    char hex[33];
    for (int i = 0; i < 16; i++) snprintf(hex + i * 2, 3, "%02x", uint8_t(esp_random()));
    token_ = hex;
    Preferences prefs;
    prefs.begin("api", false);
    prefs.putString("token", token_);
    prefs.end();
  }

  const String &value() const { return token_; }

  // Compares in constant time, so response timing doesn't leak how many characters matched.
  bool allows(const String &authorizationHeader) const {
    const String expected = "Bearer " + token_;
    if (authorizationHeader.length() != expected.length()) return false;
    uint8_t diff = 0;
    for (size_t i = 0; i < expected.length(); i++) diff |= uint8_t(authorizationHeader[i] ^ expected[i]);
    return diff == 0;
  }

 private:
  String token_;
};

// Joining a Wi-Fi network, remembering it, and staying connected.
//
// Where the password lives: in NVS ("non-volatile storage"), a small key-value area in the
// chip's flash, via the Preferences library. It survives power-off and re-flashing, and it is
// never in the source code, the build, git or the serial log. `forget` erases it.
// (NVS is not encrypted by default. Real products turn on flash encryption; fine for a bench.)
//
// Wi-Fi events: the driver tells us when we join, get an IP address or drop off. Those
// callbacks run in the Wi-Fi task, so they only set flags; loop() does the real work.
//
// Once we have an IP address:
//   - the clock syncs from internet time servers (NTP)
//   - mDNS answers to "bench.local", so other devices find us without knowing the IP
#pragma once

#include <ESPmDNS.h>
#include <Preferences.h>
#include <WiFi.h>
#include <time.h>

#include <algorithm>

class Connection {
 public:
  enum class State { NoCredentials, Connecting, Connected, Failed };
  static constexpr const char *kHostname = "bench";
  // Central European time with summer time. Change with the serial command: tz <POSIX TZ string>
  static constexpr const char *kDefaultTz = "CET-1CEST,M3.5.0,M10.5.0/3";
  static constexpr int kHistory = 60;  // seconds of signal history for the chart

  void begin() {
    WiFi.persistent(false);  // don't let the driver keep its own copy of the password
    WiFi.setAutoReconnect(true);
    WiFi.setHostname(kHostname);
    WiFi.onEvent([this](WiFiEvent_t event, WiFiEventInfo_t info) { onEvent(event, info); });

    prefs_.begin("wifi", /*readOnly=*/true);
    ssid_ = prefs_.getString("ssid", "");
    pass_ = prefs_.getString("pass", "");
    tz_ = prefs_.isKey("tz") ? prefs_.getString("tz") : String(kDefaultTz);  // isKey: no error log when unset
    prefs_.end();

    if (ssid_.isEmpty()) {
      log_i("No saved network. Type 'join <number>' after a scan.");
      state_ = State::NoCredentials;
    } else {
      log_i("Saved network found: '%s'", ssid_.c_str());
      connect();
    }
  }

  // Save a network to NVS and join it. pass is empty for open networks.
  void save(const String &ssid, const String &pass) {
    prefs_.begin("wifi", false);
    prefs_.putString("ssid", ssid);
    prefs_.putString("pass", pass);
    prefs_.end();
    ssid_ = ssid;
    pass_ = pass;
    log_i("Saved '%s' (password: %u characters, not shown)", ssid.c_str(), unsigned(pass.length()));
    connect();
  }

  void forget() {
    prefs_.begin("wifi", false);
    prefs_.remove("ssid");
    prefs_.remove("pass");
    prefs_.end();
    WiFi.disconnect();
    ssid_ = pass_ = "";
    state_ = State::NoCredentials;
    log_i("Saved network erased from NVS");
  }

  void setTimezone(const String &tz) {
    prefs_.begin("wifi", false);
    prefs_.putString("tz", tz);
    prefs_.end();
    tz_ = tz;
    if (state_ == State::Connected) configTzTime(tz_.c_str(), "pool.ntp.org", "time.cloudflare.com");
    log_i("Time zone set to '%s'", tz_.c_str());
  }

  void connect() {
    if (ssid_.isEmpty()) return;
    WiFi.disconnect();
    WiFi.begin(ssid_.c_str(), pass_.isEmpty() ? nullptr : pass_.c_str());
    state_ = State::Connecting;
    startedAt_ = millis();
    log_i("Joining '%s'...", ssid_.c_str());
  }

  // Call every loop: handles flags from the Wi-Fi task, time-outs and the signal history.
  void loop() {
    const uint32_t now = millis();
    if (gotIp_) {
      gotIp_ = false;
      state_ = State::Connected;
      connectedAt_ = now;
      log_i("Connected to '%s': IP %s, channel %d, %ld dBm", ssid_.c_str(), WiFi.localIP().toString().c_str(),
            static_cast<int>(WiFi.channel()), static_cast<long>(WiFi.RSSI()));
      // Power save lets the radio doze between router beacons and miss requests (ARP, ping, HTTP).
      // Fine for a sensor that only sends; a web server has to stay awake to be reachable.
      WiFi.setSleep(false);
      configTzTime(tz_.c_str(), "pool.ntp.org", "time.cloudflare.com");
      // mDNS follows reconnects by itself, so start it (and add the service) only once.
      if (!mdnsUp_ && MDNS.begin(kHostname)) {
        MDNS.addService("http", "tcp", 80);  // lets browsers and apps discover the web page
        mdnsUp_ = true;
      }
      if (mdnsUp_) log_i("Reachable as %s.local (try: ping %s.local, or open http://%s.local)", kHostname, kHostname, kHostname);
      else log_w("mDNS did not start");
      justConnected_ = true;
    }
    if (dropped_) {
      dropped_ = false;
      log_w("Disconnected: reason %u, %s", lastReason_, reasonHint(lastReason_));
      if (state_ == State::Connected) state_ = State::Connecting, startedAt_ = now;
    }
    if (state_ == State::Connecting && now - startedAt_ > kJoinTimeoutMs) {
      state_ = State::Failed;
      failedAt_ = now;
      log_w("Could not join '%s' within %lu s (last reason: %s). Retrying in %lu s.", ssid_.c_str(),
            static_cast<unsigned long>(kJoinTimeoutMs / 1000), reasonHint(lastReason_),
            static_cast<unsigned long>(kRetryMs / 1000));
    }
    if (state_ == State::Failed && now - failedAt_ > kRetryMs) connect();
    if (state_ == State::Connected && now - lastSample_ >= 1000) {
      lastSample_ = now;
      rssi_[head_] = int8_t(WiFi.RSSI());
      head_ = (head_ + 1) % kHistory;
      samples_ = std::min(samples_ + 1, kHistory);
    }
  }

  // True once after each successful connection (main.cpp switches to the status view).
  bool takeJustConnected() {
    const bool j = justConnected_;
    justConnected_ = false;
    return j;
  }

  State state() const { return state_; }
  const String &ssid() const { return ssid_; }
  const String &timezone() const { return tz_; }
  uint8_t lastReason() const { return lastReason_; }
  uint32_t connectingFor() const { return millis() - startedAt_; }
  uint32_t connectedFor() const { return millis() - connectedAt_; }
  bool timeSynced() const { return time(nullptr) > 1'700'000'000; }  // any date after Nov 2023
  int samples() const { return samples_; }
  int8_t rssiAt(int i) const { return rssi_[(head_ - samples_ + i + kHistory) % kHistory]; }  // 0 = oldest

  // The common disconnect reasons, in plain words.
  static const char *reasonHint(uint8_t r) {
    switch (r) {
      case 0: return "none yet";
      case 2: case 15: case 202: case 204: return "wrong password?";
      case 201: return "network not found (out of range, 5 GHz only, or name typo)";
      case 203: return "the router refused us (MAC filter, or full)";
      case 8: return "we left on purpose";
      case 200: return "lost the router's beacons (weak signal)";
      default: return WiFi.disconnectReasonName(static_cast<wifi_err_reason_t>(r));
    }
  }

 private:
  static constexpr uint32_t kJoinTimeoutMs = 20'000;
  static constexpr uint32_t kRetryMs = 30'000;

  // Runs in the Wi-Fi task: only record what happened.
  void onEvent(WiFiEvent_t event, WiFiEventInfo_t info) {
    switch (event) {
      case ARDUINO_EVENT_WIFI_STA_GOT_IP:
        gotIp_ = true;
        break;
      case ARDUINO_EVENT_WIFI_STA_DISCONNECTED:
        lastReason_ = info.wifi_sta_disconnected.reason;
        dropped_ = true;
        break;
      default:
        break;
    }
  }

  Preferences prefs_;
  String ssid_, pass_, tz_;
  State state_ = State::NoCredentials;
  volatile bool gotIp_ = false, dropped_ = false;
  volatile uint8_t lastReason_ = 0;
  bool justConnected_ = false, mdnsUp_ = false;
  uint32_t startedAt_ = 0, connectedAt_ = 0, failedAt_ = 0, lastSample_ = 0;
  int8_t rssi_[kHistory] = {};
  int head_ = 0, samples_ = 0;
};

// The shell every sound lab (S1-S8) shares: the microphone and its sampler task, the speaker, the
// level meter, the screen with its header and footer, the push button and BOOT, the on-board RGB
// LED, and the serial commands every lab has (help, view, status, mic, vol, beep, tune, rate,
// atten, quiet, plot).
//
// Which microphone? `mic auto` (the default) listens for an INMP441 on the I2S pins at start-up and
// uses it when it answers, the KY-037 otherwise. `mic ky037` / `mic inmp441` force one (saved in
// NVS, then a restart). The speaker (MAX98357A) is always started: with nothing wired it is silent.
//
// Echo guard: while the speaker plays (and 200 ms after), the lab's frame() hook gets no frames, so
// a beep is never taken for a clap. A lab that wants to hear through it sets hearSpeaker.
//
// A lab is a SoundLabSpec: its views (each a draw function, plus what a double-click does there),
// its serial commands, and hooks: setup() once the mic runs, frame() for every 4 ms frame of sound
// (with the level already updated), tick() once per screen frame, gesture() for the button.
// Each src/sound-lab-sN/main.cpp is that list.
//
// Button or BOOT: click = next view · double-click = this view's action · long press = the lab's
// long action. On-board LED, unless the lab claims it: the level as a colour (green, amber, red),
// dim while quiet.
#pragma once

#include <Arduino.h>

#include "button.h"
#include "display.h"
#include <Preferences.h>

#include "level.h"
#include "mic.h"
#include "pins.h"
#include "sound_views.h"
#include "speaker.h"

class SoundLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct SoundCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dB>"
  const char *what;  // one line for help
  void (*run)(SoundLab &lab, const String &arg, const String &lower);
};

struct SoundView {
  const char *name;  // "scope"
  void (*draw)(SoundLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct SoundLabSpec {
  const char *env;    // "sound-lab-s1"
  const char *id;     // "S1"
  const char *title;  // "Hear"
  const SoundView *views;
  int viewCount;
  int startView;
  const SoundCommand *commands;
  int commandCount;
  void (*setup)(SoundLab &lab) = nullptr;
  void (*frame)(SoundLab &lab, const snd::Frame &f, uint32_t ms) = nullptr;  // every 4 ms of sound
  void (*tick)(SoundLab &lab) = nullptr;                                    // every screen frame
  bool (*gesture)(SoundLab &lab, Gesture g, bool external) = nullptr;       // true = handled
  const char *longAction = nullptr;
  bool hearSpeaker = false;  // true: frame() keeps running while the speaker plays (S8's effects)
};

// Little sounds every lab can make (only when a speaker is wired, of course).
enum class Chime : uint8_t { Click, Ok, No, Start, Stop, Score, Hello };

class SoundLab {
 public:
  explicit SoundLab(const SoundLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    Preferences prefs;
    prefs.begin("sound", true);
    const String choice = prefs.isKey("mic") ? prefs.getString("mic") : String("auto");
    const int volume = prefs.getInt("vol", 40);
    prefs.end();
    snd::Source source = snd::Source::Ky037;
    if (choice == "inmp441") source = snd::Source::Inmp441;
    else if (choice == "auto") {
      Serial.println("Listening for an INMP441 on the I2S pins...");
      if (snd::Mic::probeInmp441()) source = snd::Source::Inmp441;
    }
    Serial.printf("Microphone: %s (mic setting: %s)\n", snd::sourceName(source), choice.c_str());
    speakerOk_ = speaker_.begin();
    speaker_.setVolume(volume);
    if (!mic_.begin(source)) {
      log_e("The microphone sampler did not start. Stopping.");
      return;
    }
    if (spec_.setup) spec_.setup(*this);
    printHelp();
    chime(Chime::Hello);
    note(sv::Note::Info, "learning the quiet...");
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    takeFrames();
    if (spec_.tick) spec_.tick(*this);
    showLed();

    const float t = millis() / 1000.0f;
    const SoundView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    sv::header(fb, spec_.id, v.name, view_, spec_.viewCount, level_.reading(), mic_.doHigh(), recording_, t, mic_.digital(),
               speaker_.busy());
    char hint[40];
    if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    sv::footer(fb, hint, note_, noteKind_, millis() - noteAt_);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  snd::Mic &mic() { return mic_; }
  snd::Speaker &speaker() { return speaker_; }
  // The level in dB SPL (INMP441 only; NAN with the KY-037, which has no known sensitivity).
  float spl() const { return mic_.splOf(level_.reading().fastDb); }
  const snd::LevelReading &level() const { return level_.reading(); }
  snd::Level &meter() { return level_; }
  Display &display() { return display_; }
  const SoundLabSpec &spec() const { return spec_; }
  int view() const { return view_; }
  // The sound clock: milliseconds of sound heard so far, advanced 64 samples' worth per frame. Every
  // detector runs on it (not millis()), so a slow screen frame never bends their timing.
  uint32_t soundMs() const { return uint32_t(soundMs_); }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself; false hands it back to the level colour.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }
  // The REC dot in the header. The recorder sets it; nothing can record without it showing.
  void setRecording(bool on) { recording_ = on; }

  void chime(Chime c) {
    if (!speakerOk_) return;
    switch (c) {
      case Chime::Click: speaker_.tone(2400, 12, syn::Wave::Square, 0.4f); break;
      case Chime::Ok: speaker_.tune("E6/16 B6/8", 240, syn::Wave::Sine); break;
      case Chime::No: speaker_.tune("C4/16 r/32 C4/8", 200, syn::Wave::Square); break;
      case Chime::Start: speaker_.tune("G5/16 C6/16", 260, syn::Wave::Triangle); break;
      case Chime::Stop: speaker_.tune("C6/16 G5/16", 260, syn::Wave::Triangle); break;
      case Chime::Score: speaker_.tune("C6/32 E6/32 G6/32 C7/16", 240, syn::Wave::Square); break;
      case Chime::Hello: speaker_.tune("C5/16 E5/16 G5/8", 220, syn::Wave::Triangle); break;
    }
  }

  // A short line for the footer, also printed to serial.
  [[gnu::format(printf, 3, 4)]] void note(sv::Note kind, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(note_, sizeof(note_), fmt, ap);
    va_end(ap);
    noteKind_ = kind;
    noteAt_ = millis();
    Serial.printf("  %s %s\n", sv::noteMark(kind), note_);
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[140];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }
  static bool decimal(const String &arg, float lo, float hi, float &out) {
    if (arg.isEmpty()) return false;
    char *end = nullptr;
    out = strtof(arg.c_str(), &end);
    return end && *end == 0 && out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    // The lab's own commands first, so a lab can give a shared word its own meaning.
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "mic") return cmdMic(lower);
    if (cmd == "vol") return cmdVol(arg);
    if (cmd == "beep") return cmdBeep(arg, lower);
    if (cmd == "tune") return cmdTune(lower);
    if (cmd == "rate") return cmdRate(arg);
    if (cmd == "atten") return cmdAtten(lower);
    if (cmd == "quiet") {
      level_.relearn();
      return note(sv::Note::Info, "shh... learning the quiet");
    }
    if (cmd == "plot") {
      plot_ = lower != "off";
      return note(sv::Note::Info, plot_ ? "plot on: one bar per 50 ms" : "plot off");
    }
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  void printHelp() {
    Serial.printf("\nSound lab %s %s  (%s)  ·  microphone: %s\n", spec_.id, spec_.title, spec_.env, snd::sourceName(mic_.source()));
    for (int i = 0; i < spec_.commandCount; i++) {
      const SoundCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "quiet", "re-learn the quiet of your room (half a second: shh)");
    Serial.printf("  %-28s %s\n", "plot [off]", "print the level as a bar every 50 ms");
    Serial.printf("  %-28s %s\n", "status", "the sampler, the microphone and the level, in numbers");
    Serial.printf("  %-28s %s\n", "mic [auto|ky037|inmp441]", "which microphone (saved; restarts)");
    Serial.printf("  %-28s %s\n", "vol <0-100>", "speaker volume (saved, default 40)");
    Serial.printf("  %-28s %s\n", "beep [Hz] [wave]", "a test tone on the speaker (sine square triangle saw noise)");
    Serial.printf("  %-28s %s\n", "tune <name>", "play a tune: hello scale twinkle ode alarm");
    Serial.printf("  %-28s %s\n", "rate <Hz>", "sample rate, 2000-48000 (default 16000)");
    Serial.printf("  %-28s %s\n", "atten <0|2.5|6|12>", "the ADC's input range (default 12 dB = 0-3.1 V)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const snd::LevelReading &r = level_.reading();
    Serial.printf("sampler: %lu Hz asked, %lu Hz measured · frames dropped %lu · DMA overruns %lu\n",
                  static_cast<unsigned long>(mic_.rate()), static_cast<unsigned long>(mic_.measuredRate()),
                  static_cast<unsigned long>(mic_.framesDropped()), static_cast<unsigned long>(mic_.overruns()));
    if (mic_.digital())
      Serial.printf("INMP441: 24-bit, offset %d · last 100 ms %d..%d of +-%d%s · dB SPL = dBFS + %.0f\n", int(mic_.biasRaw()), mic_.rawLow(),
                    mic_.rawHigh(), mic_.rawMax(), mic_.clipping() ? " CLIPPING" : "", snd::Mic::kInmp441Spl);
    else
      Serial.printf("KY-037 on the ADC: attenuation %s · bias %d mV (raw %d) · last 100 ms raw %d..%d%s · %s\n", snd::attenName(mic_.atten()),
                    mic_.biasMv(), int(mic_.biasRaw()), mic_.rawLow(), mic_.rawHigh(), mic_.clipping() ? " CLIPPING" : "",
                    mic_.calibrated() ? "eFuse calibration" : "no calibration (straight-line mV)");
    Serial.printf("level: %.1f dBFS fast, %.1f slow, floor %.1f dBFS · %.1f dB above the quiet · peak %.1f dBFS\n", r.fastDb, r.slowDb,
                  r.floorDb, r.above(), r.peakDb);
    if (mic_.digital()) Serial.printf("sound level: about %.0f dB SPL (unweighted)\n", spl());
    else Serial.printf("comparator DO: %s now, %lu rising edges\n", mic_.doHigh() ? "HIGH" : "low", static_cast<unsigned long>(mic_.doRises()));
    Serial.printf("speaker: volume %d, %s\n", speaker_.volume(), speaker_.busy() ? "playing" : "quiet");
  }

  void cmdRate(const String &arg) {
    long hz = 0;
    if (!number(arg, 2000, 48000, hz)) return warn("rate <Hz>, 2000-48000. Now %lu", static_cast<unsigned long>(mic_.rate()));
    mic_.reconfigure(uint32_t(hz), mic_.atten());
    level_ = snd::Level(snd::kChunk * 1000.0f / float(hz));  // a frame is 64 samples: its length changes
    note(sv::Note::Info, "rate %ld Hz", hz);
  }

  void cmdMic(const String &lower) {
    if (lower != "auto" && lower != "ky037" && lower != "inmp441")
      return warn("mic auto | mic ky037 | mic inmp441   (now: %s)", snd::sourceName(mic_.source()));
    Preferences prefs;
    prefs.begin("sound", false);
    prefs.putString("mic", lower);
    prefs.end();
    Serial.printf("mic %s saved. Restarting to switch...\n", lower.c_str());
    Serial.flush();
    delay(200);
    ESP.restart();
  }

  void cmdVol(const String &arg) {
    long v = 0;
    if (!number(arg, 0, 100, v)) return warn("vol <0-100>   (now %d)", speaker_.volume());
    speaker_.setVolume(int(v));
    Preferences prefs;
    prefs.begin("sound", false);
    prefs.putInt("vol", int(v));
    prefs.end();
    chime(Chime::Click);
    note(sv::Note::Info, "volume %ld", v);
  }

  void cmdBeep(const String &arg, const String &lower) {
    float hz = 880;
    syn::Wave wave = syn::Wave::Sine;
    const int sp = lower.indexOf(' ');
    if (!arg.isEmpty() && !decimal(sp < 0 ? arg : arg.substring(0, sp), 20, 8000, hz)) return warn("beep [Hz 20-8000] [sine|square|triangle|saw|noise]");
    if (sp > 0 && !syn::parseWave(lower.substring(sp + 1).c_str(), wave)) return warn("wave: sine square triangle saw noise");
    speaker_.tone(hz, 400, wave);
    note(sv::Note::Info, "beep %.0f Hz %s", hz, syn::waveName(wave));
  }

  void cmdTune(const String &lower) {
    static const struct {
      const char *name, *notes;
      int bpm;
    } kTunes[] = {
        {"hello", "C5/16 E5/16 G5/8", 220},
        {"scale", "C4/8 D4/8 E4/8 F4/8 G4/8 A4/8 B4/8 C5/4", 160},
        {"twinkle", "C5/4 C5/4 G5/4 G5/4 A5/4 A5/4 G5/2 F5/4 F5/4 E5/4 E5/4 D5/4 D5/4 C5/2", 160},
        {"ode", "E5/4 E5/4 F5/4 G5/4 G5/4 F5/4 E5/4 D5/4 C5/4 C5/4 D5/4 E5/4 E5/4. D5/8 D5/2", 150},
        {"alarm", "A5/16 E5/16 A5/16 E5/16 A5/16 E5/16 A5/16 E5/16", 200},
    };
    for (const auto &t : kTunes)
      if (lower == t.name) {
        speaker_.tune(t.notes, t.bpm);
        return note(sv::Note::Info, "playing %s", t.name);
      }
    warn("tune hello | scale | twinkle | ode | alarm");
  }

  void cmdAtten(const String &lower) {
    if (mic_.digital()) return warn("atten is for the KY-037's ADC: the INMP441 has its own converter inside");
    adc_atten_t a;
    if (lower == "0") a = ADC_ATTEN_DB_0;
    else if (lower == "2.5") a = ADC_ATTEN_DB_2_5;
    else if (lower == "6") a = ADC_ATTEN_DB_6;
    else if (lower == "12" || lower == "11") a = ADC_ATTEN_DB_12;
    else return warn("atten 0 | 2.5 | 6 | 12   (now %s)", snd::attenName(mic_.atten()));
    mic_.reconfigure(mic_.rate(), a);
    level_.relearn();
    note(sv::Note::Info, "attenuation %s", snd::attenName(a));
  }

  // All frames the sampler has queued since the last screen frame: level first, then the lab.
  void takeFrames() {
    snd::Frame f;
    while (mic_.frame(f)) {
      soundMs_ += snd::kChunk * 1000.0 / mic_.rate();
      const uint32_t ms = uint32_t(soundMs_);
      level_.push(f.rms, ms);
      // The echo guard: the board's own sounds are not claps, knocks or voices.
      if (spec_.frame && (spec_.hearSpeaker || !speaker_.recentlyLoud(200))) spec_.frame(*this, f, ms);
      if (plot_ && ms - plotAt_ >= 50) plotAt_ = ms, printPlot();
    }
  }

  void printPlot() {
    const snd::LevelReading &r = level_.reading();
    char bar[41];
    const int n = int(snd::meterFraction(r.instAbove(), 60) * 40);
    for (int i = 0; i < 40; i++) bar[i] = i < n ? '#' : (i == int(snd::meterFraction(r.peakDb - r.floorDb, 60) * 40) ? '|' : ' ');
    bar[40] = 0;
    if (mic_.digital()) Serial.printf("%5.1f dB |%s| %3.0f dB SPL\n", r.instAbove(), bar, mic_.splOf(r.instDb));
    else Serial.printf("%5.1f dB |%s| DO %c\n", r.instAbove(), bar, mic_.doHigh() ? '1' : '0');
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) >= 0x20 && buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  void showLed() {
    if (ledClaimed_) return;
    uint8_t r = 0, g = 0, b = 0;
    if (recording_) r = 90;  // the recorder always shows itself, here too
    else {
      // 8 brightness steps, so the LED (a whole WS2812 frame per write) only changes when it should.
      const float above = level_.reading().above();
      const uint8_t v = uint8_t(4 + int(snd::meterFraction(above, 50) * 7) * 12);
      if (above < 25) g = v;
      else if (above < 40) r = v, g = v / 2;
      else r = v;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const SoundLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  snd::Mic mic_;
  snd::Speaker speaker_;
  snd::Level level_;
  bool speakerOk_ = false;
  int view_;
  bool ledClaimed_ = false, recording_ = false, plot_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, plotAt_ = 0;
  double soundMs_ = 0;
  char note_[64] = "";
  sv::Note noteKind_ = sv::Note::Info;
  uint32_t noteAt_ = 0;
};

// When does the voice-activated recorder (S4) start and stop?
//
//   off ──arm──> ARMED ──louder than startDb──> RECORDING ──quiet for holdMs──> clip saved, ARMED again
//                  │                               │ (or maxMs reached, or `stop`)
//                  └──── rec (by hand) ────────────┘
//
// Pre-roll: the first syllable is already over by the time the level crosses startDb. The
// sampler keeps the last 4 s of sound in a ring anyway, so the clip simply starts prerollMs
// *before* the trigger. Hold: speech has short pauses; waiting holdMs of quiet keeps one
// sentence in one clip. Clips shorter than minMs (a door slam) are thrown away when automatic.
//
// Everything is counted in samples (the sampler's running sample number), so the recorder can
// copy exactly that stretch out of the ring. Pure C++: host-tested in kit/test/host/sound_dsp_test.cpp.
#pragma once

#include <stdint.h>

namespace snd {

struct TriggerConfig {
  float startDb = 15;        // dB above the quiet that starts a recording
  uint32_t holdMs = 1200;    // quiet for this long ends it
  uint32_t prerollMs = 500;  // keep this much from before the trigger
  uint32_t maxMs = 20000;    // longest clip
  uint32_t minMs = 400;      // automatic clips shorter than this are dropped
};

class Trigger {
 public:
  enum class State : uint8_t { Off, Armed, Recording };
  enum class Action : uint8_t { None, Start, Save, Drop };
  struct Result {
    Action action = Action::None;
    uint32_t from = 0, to = 0;  // sample numbers: Start = from; Save/Drop = from..to
  };

  TriggerConfig config;

  explicit Trigger(uint32_t rate) : rate_(rate) {}
  void setRate(uint32_t rate) { rate_ = rate; }

  void arm(bool on) {
    if (state_ != State::Recording) state_ = on ? State::Armed : State::Off;
    armed_ = on;
  }
  bool armed() const { return armed_; }
  State state() const { return state_; }
  bool manual() const { return manual_; }
  uint32_t from() const { return from_; }

  // Start now, by hand: also takes the pre-roll. `now` = the newest sample number.
  Result start(uint32_t now) {
    if (state_ == State::Recording) return {};
    manual_ = true;
    return begin(now);
  }

  // Stop now, by hand (or because the clip store is full).
  Result stop(uint32_t now) {
    if (state_ != State::Recording) return {};
    return end(now, Action::Save);
  }

  // One frame: its level above the quiet, and the sample number at its end.
  Result push(float aboveDb, uint32_t now) {
    switch (state_) {
      case State::Off: return {};
      case State::Armed:
        if (aboveDb >= config.startDb) {
          manual_ = false;
          return begin(now);
        }
        return {};
      case State::Recording: {
        if (aboveDb >= config.startDb * 0.6f) lastLoud_ = now;  // a little below the start: speech dips
        if (now - from_ >= samples(config.maxMs)) return end(now, Action::Save);
        if (!manual_ && now - lastLoud_ >= samples(config.holdMs)) {
          const uint32_t loudFor = lastLoud_ - trigger_;
          // Keep the hold's quiet tail short: half a second after the last loud frame is enough.
          const uint32_t to = lastLoud_ + samples(500) < now ? lastLoud_ + samples(500) : now;
          return end(to, loudFor + samples(100) >= samples(config.minMs) ? Action::Save : Action::Drop);
        }
        return {};
      }
    }
    return {};
  }

 private:
  uint32_t samples(uint32_t ms) const { return uint32_t(uint64_t(ms) * rate_ / 1000); }

  Result begin(uint32_t now) {
    const uint32_t pre = samples(config.prerollMs);
    from_ = now > pre ? now - pre : 0;
    trigger_ = lastLoud_ = now;
    state_ = State::Recording;
    return {Action::Start, from_, now};
  }

  Result end(uint32_t to, Action a) {
    state_ = armed_ ? State::Armed : State::Off;
    manual_ = false;
    return {a, from_, to};
  }

  uint32_t rate_;
  State state_ = State::Off;
  bool armed_ = false, manual_ = false;
  uint32_t from_ = 0, trigger_ = 0, lastLoud_ = 0;
};

}  // namespace snd

// Drawing pieces every sound lab shares (320 x 170, landscape):
//   header   the lab id + the view's name, view dots, and the ear: a live level bar, the
//            comparator's DO lamp, and a red REC dot whenever anything is being recorded
//   footer   the button hint on the left, the latest note on the right (fading after 6 s)
//   wave     samples as a waveform in a box, scaled to fit
//   meter    a horizontal level bar with the floor, peak hold and a limit mark
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include "color.h"
#include "frame_buffer.h"
#include "level.h"

namespace sv {

constexpr int kW = 320, kH = 170, kTop = 30, kBottom = kH - 12;
// The sound track's colour on the bench palette, plus one for "recording".
constexpr uint16_t kSound = rgb(255, 128, 200);
constexpr uint16_t kRec = rgb(255, 60, 60);
constexpr uint16_t kPanel = rgb(20, 28, 40);

inline int textWidth(FrameBuffer &fb, const char *s) {
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void small(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(nullptr);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void bold(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void big(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold24pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

// A label over a value, in a column.
inline void stat(FrameBuffer &fb, int x, int y, const char *label, const char *value, uint16_t c = pal::ink) {
  small(fb, x, y, pal::muted, label);
  bold(fb, x, y + 22, c, value);
}

// Green while calm, amber when loud, coral when very loud (dB above the quiet).
inline uint16_t levelColour(float above) { return above < 25 ? pal::teal : above < 40 ? pal::amber : pal::coral; }

// The ear in the header: 10 segments of level, then the DO lamp (KY-037) or a small "D" (the digital
// INMP441), sound waves while the speaker plays, and the REC dot.
inline void ear(FrameBuffer &fb, int x, int y, const snd::LevelReading &r, bool doHigh, bool rec, float t, bool digital, bool speaking) {
  const int lit = int(snd::meterFraction(r.above(), 50) * 10 + 0.5f);
  for (int i = 0; i < 10; i++) fb.fillRect(x + i * 4, y, 3, 10, i < lit ? levelColour(i * 5.0f) : pal::dim);
  if (digital) small(fb, x + 45, y + 2, pal::teal, "D");
  else fb.fillCircle(x + 48, y + 5, 3, doHigh ? pal::amber : pal::dim);
  if (speaking)
    for (int i = 0; i < 2; i++) fb.drawCircleHelper(x - 8 + i * 3, y + 5, 3 + i * 3, 0x2 | 0x4, kSound);
  if (rec && fmodf(t, 1.0f) < 0.6f) fb.fillCircle(x + 60, y + 5, 4, kRec);
}

inline void header(FrameBuffer &fb, const char *labId, const char *view, int index, int count, const snd::LevelReading &r, bool doHigh,
                   bool rec, float t, bool digital = false, bool speaking = false) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(kSound);
  fb.setCursor(8, 18);
  fb.print(labId);
  fb.print(" ");
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  ear(fb, kW - 74, 10, r, doHigh, rec, t, digital, speaking);
  const int firstDot = kW - 92 - (count - 1) * 9;
  for (int i = 0; i < count; i++) fb.fillCircle(firstDot + i * 9, 15, 3, i == index ? pal::ink : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

enum class Note : uint8_t { Info, Good, Warn, Bad };

inline uint16_t noteColour(Note k) {
  switch (k) {
    case Note::Good: return pal::teal;
    case Note::Warn: return pal::amber;
    case Note::Bad: return pal::coral;
    default: return pal::muted;
  }
}

inline const char *noteMark(Note k) {
  switch (k) {
    case Note::Good: return "+";
    case Note::Warn: return "!";
    case Note::Bad: return "x";
    default: return "-";
  }
}

inline void footer(FrameBuffer &fb, const char *hint, const char *note, Note kind, uint32_t noteAgeMs) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  small(fb, 6, kH - 9, pal::muted, hint);
  if (!note || !note[0] || noteAgeMs > 6000) return;
  char right[30];
  strlcpy(right, note, sizeof(right));
  fb.setFont(nullptr);
  const uint16_t c = mix(noteColour(kind), pal::night, uint8_t(noteAgeMs > 4000 ? (noteAgeMs - 4000) * 200 / 2000 : 0));
  small(fb, kW - 6 - textWidth(fb, right), kH - 9, c, right);
}

// Samples as a waveform: one column per pixel, min..max of the samples that fall in it, so nothing
// is hidden between pixels. `scale` = how many int16 units half the box height shows.
inline void wave(FrameBuffer &fb, int x, int y, int w, int h, const int16_t *s, int n, float scale, uint16_t c) {
  const int mid = y + h / 2;
  fb.drawFastHLine(x, mid, w, pal::dim);
  if (n <= 0 || scale <= 0) return;
  const float k = (h / 2 - 1) / scale;
  for (int col = 0; col < w; col++) {
    const int a = col * n / w, b = std::max(a + 1, (col + 1) * n / w);
    int lo = 32767, hi = -32768;
    for (int i = a; i < b && i < n; i++) lo = std::min<int>(lo, s[i]), hi = std::max<int>(hi, s[i]);
    const int y0 = std::max(y, std::min(y + h - 1, mid - int(hi * k))), y1 = std::max(y, std::min(y + h - 1, mid - int(lo * k)));
    fb.drawFastVLine(x + col, y0, y1 - y0 + 1, c);
  }
}

// The biggest |sample| in a block, for auto-scaling a wave (never below `minScale`).
inline float autoScale(const int16_t *s, int n, float minScale = 256) {
  int m = 0;
  for (int i = 0; i < n; i++) m = std::max(m, std::abs(int(s[i])));
  return std::max(minScale, float(m) * 1.1f);
}

// A level bar: fill up to `above` dB (of rangeDb), the peak hold as a tick, an optional limit line.
inline void meter(FrameBuffer &fb, int x, int y, int w, int h, const snd::LevelReading &r, float rangeDb = 60, float limitDb = -1) {
  fb.fillRoundRect(x, y, w, h, 3, kPanel);
  const int fill = int(snd::meterFraction(r.above(), rangeDb) * (w - 2));
  // Coloured in zones, so the colour says how loud even without reading the number.
  for (int i = 0; i < fill; i += 3) fb.fillRect(x + 1 + i, y + 2, 2, h - 4, levelColour(float(i) / (w - 2) * rangeDb));
  const float peakAbove = r.peakDb - r.floorDb;
  const int px = x + 1 + int(snd::meterFraction(peakAbove, rangeDb) * (w - 2));
  fb.drawFastVLine(px, y, h, pal::ink);
  if (limitDb > 0) {
    const int lx = x + 1 + int(snd::meterFraction(limitDb, rangeDb) * (w - 2));
    for (int j = y - 3; j < y + h + 3; j += 2) fb.drawPixel(lx, j, pal::coral);
  }
}

}  // namespace sv

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// The 1.9" ST7789 screen plus an off-screen frame buffer, set up the way every lesson since 03 uses it.
// Draw into fb() with the normal Adafruit GFX calls, then push() sends the whole picture at once.
#pragma once

#include <Adafruit_ST7789.h>
#include <SPI.h>

#include "frame_buffer.h"
#include "pins.h"

class Display {
 public:
  static constexpr int16_t kW = 320, kH = 170;  // landscape

  Display() : tft_(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST), fb_(kW, kH) {}

  // Returns false if there is no memory for the frame buffer.
  bool begin(uint32_t spiHz = 40'000'000) {
    // Backlight through PWM so it can be dimmed (setBacklight). Full brightness to start.
    ledcAttach(PIN_TFT_BL, 5000, 8);
    ledcWrite(PIN_TFT_BL, 255);
    SPI.begin(PIN_TFT_SCLK, -1, PIN_TFT_MOSI, PIN_TFT_CS);
    tft_.init(170, 320);
    tft_.setSPISpeed(spiHz);
    tft_.setRotation(1);
    tft_.fillScreen(0);
    return fb_.begin();
  }

  FrameBuffer &fb() { return fb_; }
  // 0 = off, 255 = full brightness.
  void setBacklight(uint8_t level) { ledcWrite(PIN_TFT_BL, level); }
  void push() { tft_.drawRGBBitmap(0, 0, fb_.pixels(), kW, kH); }

 private:
  Adafruit_ST7789 tft_;
  FrameBuffer fb_;
};

// How loud is it? Decibels from the microphone's samples, the way a sound level meter shows them.
//
// The sampler (mic.h) cuts the sound into frames of 64 samples (4 ms at 16 kHz) and hands each
// frame's RMS (root mean square: the "average strength" of a wave that swings + and -) and peak.
//
// Decibels: our ears hear ratios, not differences. dB = 20 x log10(level / reference), so every
// +6 dB doubles the wave's height and +20 dB is ten times. Two scales here:
//   dBFS     relative to the ADC's full scale (0 dBFS = the loudest the ADC can show). Always <= 0.
//   above    dB above the quietest your room gets (the noise floor). 0 = silence, 20 = talking
//            close by, 40+ = a clap at arm's length. This is the number the labs mostly use.
// Neither is "dB SPL" (what a calibrated meter shows): that would need a reference microphone.
//
// Fast and slow: real meters smooth the level with a 125 ms ("fast") or 1 s ("slow") time
// constant. We smooth the power (RMS squared) the same way, then convert to dB.
//
// The noise floor follows the quiet: it drops at once to anything quieter and creeps up by
// 0.5 dB a second, so a minute of steady noise (a fan) becomes the new "quiet". `quiet` re-learns it.
//
// Pure C++ (no Arduino): host-tested in kit/test/host/sound_dsp_test.cpp.
#pragma once

#include <math.h>
#include <stdint.h>

namespace snd {

constexpr float kFloorDb = -96.0f;  // what silence (an RMS below 1 of 32768) reads as

inline float toDb(float rms) { return rms < 0.5f ? kFloorDb : 20.0f * log10f(rms / 32768.0f); }
inline float powerToDb(float power) { return power < 0.25f ? kFloorDb : 10.0f * log10f(power / (32768.0f * 32768.0f)); }

// Smoothing factor for a time constant, for frames of frameMs.
inline float alphaFor(float tauMs, float frameMs) { return 1.0f - expf(-frameMs / tauMs); }

struct LevelReading {
  float instDb = kFloorDb;  // this frame alone (4 ms): claps and knocks live here
  float fastDb = kFloorDb;  // 125 ms
  float slowDb = kFloorDb;  // 1 s
  float peakDb = kFloorDb;  // the highest instDb lately, held 1.5 s then falling 20 dB/s
  float floorDb = 0;         // the noise floor
  float above() const { return fastDb > floorDb ? fastDb - floorDb : 0.0f; }
  float instAbove() const { return instDb > floorDb ? instDb - floorDb : 0.0f; }
  float slowAbove() const { return slowDb > floorDb ? slowDb - floorDb : 0.0f; }
};

class Level {
 public:
  explicit Level(float frameMs = 4.0f)
      : frameMs_(frameMs), aFast_(alphaFor(125, frameMs)), aSlow_(alphaFor(1000, frameMs)), floorRise_(0.5f * frameMs / 1000.0f) {}

  // One frame: its RMS (in int16 units) and the time it ended (ms).
  void push(float rms, uint32_t ms) {
    const float power = rms * rms;
    if (frames_ == 0) fastP_ = slowP_ = power;
    fastP_ += aFast_ * (power - fastP_);
    slowP_ += aSlow_ * (power - slowP_);
    r_.instDb = toDb(rms);
    r_.fastDb = powerToDb(fastP_);
    r_.slowDb = powerToDb(slowP_);

    // Peak hold: jump up at once, hold 1.5 s, then fall 20 dB a second.
    if (r_.instDb >= r_.peakDb) r_.peakDb = r_.instDb, peakAt_ = ms;
    else if (ms - peakAt_ > 1500) r_.peakDb -= 20.0f * frameMs_ / 1000.0f;

    // Noise floor: the average power of the first half second, then it follows the quiet.
    if (learned_ < learnFrames()) learnP_ += power, r_.floorDb = powerToDb(learnP_ / float(++learned_));
    else if (r_.fastDb < r_.floorDb) r_.floorDb = r_.fastDb;
    else r_.floorDb += floorRise_;
    frames_++;
  }

  // Forget the floor: the next half second becomes the new quiet.
  void relearn() {
    learned_ = 0;
    learnP_ = 0;
  }
  bool learning() const { return learned_ < learnFrames(); }

  const LevelReading &reading() const { return r_; }

 private:
  uint32_t learnFrames() const { return uint32_t(500 / frameMs_); }

  float frameMs_, aFast_, aSlow_, floorRise_;
  float fastP_ = 0, slowP_ = 0, learnP_ = 0;
  uint32_t frames_ = 0, learned_ = 0, peakAt_ = 0;
  LevelReading r_;
};

// A 0-1 position for a meter that shows `rangeDb` dB above the floor.
inline float meterFraction(float aboveDb, float rangeDb = 60.0f) {
  const float f = aboveDb / rangeDb;
  return f < 0 ? 0 : f > 1 ? 1 : f;
}

}  // namespace snd

// The microphone, whichever one is wired: sampled 16 000 times a second, the same pipeline after.
//
// Two sources, one class:
//   KY-037   analog. Its AO pin is a small wave on top of a steady voltage (the "bias"). The ESP32's
//            own ADC measures it, 12 bits (0-4095). No amplifier: a good loudness sensor, hissy for
//            voices. Its DO pin is the comparator's yes/no, watched by an interrupt.
//   INMP441  digital. The microphone has its own amplifier and a 24-bit ADC inside, and sends
//            numbers over I2S (a clock, a left/right line, a data line). No bias, no ADC noise, and
//            its sensitivity is in the datasheet (-26 dBFS at 94 dB SPL), so S2 can show real dB SPL.
//
// Why not analogRead() in loop()? It takes one sample when asked, and loop() also draws the screen
// (~40 ms a frame), so we would get a few samples a frame, unevenly spaced: useless for sound.
// Both sources run on their own clock instead: the ADC in "continuous" mode, the I2S peripheral as
// the microphone's clock master, each with DMA (direct memory access) moving results into RAM with
// no CPU involved. A sampler task on core 0 (the screen loop runs on core 1) picks them up and:
//
//   1. removes the DC part: a very slow average follows it, and every sample becomes "raw - average",
//      a wave around 0 (the KY-037's bias, or the INMP441's small offset).
//   2. scales it to 16 bits and stores it in a 4-second ring in PSRAM. Each sample has a running
//      number (`written()`): the scope, FFT and recorder copy stretches out of the ring by number,
//      whenever they like, without stopping the sampler.
//   3. every 64 samples (4 ms) measures the chunk's RMS and peak and queues it as a Frame. The lab
//      shell turns frames into the level meter and the clap, knock and beat detectors.
//
// Pins (kit/include/pins.h): KY-037 AO must be an ADC1 pin (ADC2 is busy while Wi-Fi is on). The
// INMP441 uses the I2S0 peripheral; the speaker (speaker.h) uses I2S1, so both can run at once.
#pragma once

#include <Arduino.h>
#include <driver/gpio.h>
#include <driver/i2s_std.h>
#include <esp_adc/adc_cali.h>
#include <esp_adc/adc_cali_scheme.h>
#include <esp_adc/adc_continuous.h>
#include <esp_heap_caps.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

#include <atomic>

#include "pins.h"

namespace snd {

constexpr int kChunk = 64;  // samples per frame

enum class Source : uint8_t { Ky037, Inmp441 };
inline const char *sourceName(Source s) { return s == Source::Inmp441 ? "INMP441 (I2S, digital)" : "KY-037 (ADC, analog)"; }
inline const char *sourceShort(Source s) { return s == Source::Inmp441 ? "INMP441" : "KY-037"; }

struct Frame {
  uint32_t end;   // the sample number just after this frame
  float rms;      // int16 units
  int16_t peak;   // the biggest |sample|
};

// Attenuation (KY-037 only): how much the ADC divides the input before measuring. More = a wider
// voltage range, fewer millivolts per step. The S3's usable ranges, roughly: 0 dB to ~0.95 V,
// 2.5 dB ~1.25 V, 6 dB ~1.75 V, 12 dB ~3.1 V. The bias must sit inside the range, with room for the wave.
inline const char *attenName(adc_atten_t a) {
  switch (a) {
    case ADC_ATTEN_DB_0: return "0 dB (0-0.95 V)";
    case ADC_ATTEN_DB_2_5: return "2.5 dB (0-1.25 V)";
    case ADC_ATTEN_DB_6: return "6 dB (0-1.75 V)";
    default: return "12 dB (0-3.1 V)";
  }
}
inline int attenTopMv(adc_atten_t a) { return a == ADC_ATTEN_DB_0 ? 950 : a == ADC_ATTEN_DB_2_5 ? 1250 : a == ADC_ATTEN_DB_6 ? 1750 : 3100; }

class Mic {
 public:
  static constexpr uint32_t kRing = 1 << 16;  // samples: 4.1 s at 16 kHz, 128 KB of PSRAM
  static constexpr uint32_t kMask = kRing - 1;
  // INMP441: its 24-bit sample >> 6 = our int16. That's 12 dB of gain over plain 16 bits: a quiet
  // room still uses a few bits, and it clips only around 114 dB SPL (a clap right at the mic).
  static constexpr int kI2sShift = 8 + 6;
  // dB SPL = our RMS dBFS + this (INMP441 only): -26 dBFS at 94 dB SPL, +12 dB for the shift above,
  // +3 dB because a full-scale sine has an RMS 3 dB under its peak. About +-2 dB, no A-weighting.
  static constexpr float kInmp441Spl = 94.0f + 26.0f - 12.0f + 3.0f;

  // Is an INMP441 answering on the I2S pins? With the data line pulled down, a missing microphone
  // reads as zeros; a real one never sends 100 ms of perfect silence. Takes ~0.3 s.
  static bool probeInmp441() {
    i2s_chan_handle_t rx = nullptr;
    if (!startI2s(rx, 16000)) return false;
    static int32_t buf[512];
    bool alive = false;
    const uint32_t until = millis() + 350;
    while (millis() < until) {
      size_t got = 0;
      if (i2s_channel_read(rx, buf, sizeof(buf), &got, 50) != ESP_OK) continue;
      if (millis() + 150 > until)  // the INMP441 needs ~85 ms to wake up: judge only the end
        for (size_t i = 0; i < got / 4; i++) alive |= buf[i] != 0 && buf[i] != -1;
    }
    i2s_channel_disable(rx);
    i2s_del_channel(rx);
    return alive;
  }

  bool begin(Source source, uint32_t rate = 16000, adc_atten_t atten = ADC_ATTEN_DB_12) {
    ring_ = static_cast<int16_t *>(heap_caps_calloc(kRing, sizeof(int16_t), MALLOC_CAP_SPIRAM));
    frames_ = xQueueCreate(256, sizeof(Frame));  // ~1 s of frames: loop() can be slow for a while
    if (!ring_ || !frames_) {
      log_e("Mic: no memory for the sample ring");
      return false;
    }
    source_ = source;
    rate_ = wantRate_ = rate;
    atten_ = wantAtten_ = atten;
    if (!startSource()) return false;
    if (source_ == Source::Ky037) {
      pinMode(PIN_MIC_DO, INPUT);  // the module drives DO itself (its own pull-up resistor)
      attachInterruptArg(digitalPinToInterrupt(PIN_MIC_DO), onDoEdge, this, RISING);
    }
    xTaskCreatePinnedToCore(task, "mic", 4096, this, 5, &task_, 0);
    return true;
  }

  // Change the sample rate and/or attenuation (KY-037). The task restarts the source between reads.
  void reconfigure(uint32_t rate, adc_atten_t atten) {
    wantRate_ = rate;
    wantAtten_ = atten;
    reconfigure_ = true;
  }

  Source source() const { return source_; }
  bool digital() const { return source_ == Source::Inmp441; }
  uint32_t rate() const { return rate_; }
  adc_atten_t atten() const { return atten_; }
  // dB SPL for a dBFS level, or NAN when the microphone has no known sensitivity (KY-037).
  float splOf(float dbfs) const { return digital() ? dbfs + kInmp441Spl : NAN; }

  // ---- The sound -------------------------------------------------------------------------------

  // Running sample number: how many samples have ever been stored.
  uint32_t written() const { return written_.load(std::memory_order_acquire); }

  // Copy n samples starting at sample number `from`. False if they're no longer (or not yet) in the ring.
  bool copy(uint32_t from, int16_t *out, uint32_t n) const {
    const uint32_t w = written();
    if (from + n > w || w - from > kRing - 1024) return false;  // 1024 = margin for the writer
    for (uint32_t i = 0; i < n; i++) out[i] = ring_[(from + i) & kMask];
    return true;
  }
  // The newest n samples.
  bool latest(int16_t *out, uint32_t n) const {
    const uint32_t w = written();
    return w >= n && copy(w - n, out, n);
  }

  // The next frame, if any (from loop()).
  bool frame(Frame &f) { return xQueueReceive(frames_, &f, 0) == pdTRUE; }

  // ---- The raw signal (S1) ---------------------------------------------------------------------

  // The slow average of the raw values: KY-037 0-4095 ADC steps, INMP441 24-bit units.
  float biasRaw() const { return dc_; }
  int biasMv() const { return digital() ? 0 : toMv(int(dc_)); }
  int toMv(int raw) const {
    if (digital()) return 0;
    int mv = 0;
    if (cali_ && adc_cali_raw_to_voltage(cali_, raw, &mv) == ESP_OK) return mv;
    return raw * attenTopMv(atten_) / 4095;  // no calibration in eFuse: a straight-line guess
  }
  // Lowest and highest raw value over the last ~100 ms: is the wave hitting the ends (clipping)?
  int rawLow() const { return rawLow_; }
  int rawHigh() const { return rawHigh_; }
  int rawMax() const { return digital() ? (1 << 23) - 1 : 4095; }
  bool clipping() const { return digital() ? (rawHigh_ >= rawMax() - 16 || rawLow_ <= -rawMax() + 16) : (rawLow_ <= 0 || rawHigh_ >= 4095); }
  bool calibrated() const { return cali_ != nullptr; }

  uint32_t overruns() const { return overruns_; }        // the DMA pool overflowed: samples lost
  uint32_t framesDropped() const { return dropped_; }    // loop() was too slow to take frames
  uint32_t measuredRate() const { return measuredRate_; }  // samples counted in the last second

  // ---- The comparator (KY-037's DO) ------------------------------------------------------------

  bool doHigh() const { return source_ == Source::Ky037 && digitalRead(PIN_MIC_DO) == HIGH; }
  uint32_t doRises() const { return doRises_; }
  uint32_t doLastRiseUs() const { return doLastRiseUs_; }

 private:
  static bool startI2s(i2s_chan_handle_t &rx, uint32_t rate) {
    i2s_chan_config_t cc = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    cc.dma_frame_num = 256;
    if (i2s_new_channel(&cc, nullptr, &rx) != ESP_OK) return log_e("Mic: no I2S channel"), false;
    // Philips I2S, 32-bit slots, mono: the INMP441 sends 24 bits, MSB first, in the left slot (L/R
    // pin to GND). The ESP32-S3 drives SCK at rate x 64 (2 slots x 32 bits) = 1.024 MHz at 16 kHz.
    i2s_std_config_t sc = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(rate),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_MONO),
        .gpio_cfg = {.mclk = I2S_GPIO_UNUSED, .bclk = gpio_num_t(PIN_I2S_MIC_SCK), .ws = gpio_num_t(PIN_I2S_MIC_WS),
                     .dout = I2S_GPIO_UNUSED, .din = gpio_num_t(PIN_I2S_MIC_SD), .invert_flags = {}},
    };
    if (i2s_channel_init_std_mode(rx, &sc) != ESP_OK || i2s_channel_enable(rx) != ESP_OK) {
      i2s_del_channel(rx);
      rx = nullptr;
      return log_e("Mic: I2S set-up failed"), false;
    }
    gpio_pulldown_en(gpio_num_t(PIN_I2S_MIC_SD));  // nothing wired = zeros, not noise
    return true;
  }

  bool startSource() {
    if (source_ == Source::Inmp441) {
      if (!startI2s(rx_, rate_)) return false;
      dcRate_ = 1.0f / 8192.0f;
      gain_ = 1.0f / float(1 << (kI2sShift - 8));
      log_i("Mic: INMP441 on I2S (SCK %d, WS %d, SD %d) at %lu Hz, 24-bit", PIN_I2S_MIC_SCK, PIN_I2S_MIC_WS, PIN_I2S_MIC_SD,
            static_cast<unsigned long>(rate_));
      return true;
    }
    if (adc_continuous_io_to_channel(PIN_MIC_AO, &unit_, &channel_) != ESP_OK || unit_ != ADC_UNIT_1)
      return log_e("Mic: GPIO %d is not an ADC1 pin (use GPIO 1-10)", PIN_MIC_AO), false;
    adc_continuous_handle_cfg_t hc = {};
    hc.max_store_buf_size = 4096;
    hc.conv_frame_size = 256 * SOC_ADC_DIGI_DATA_BYTES_PER_CONV;
    if (adc_continuous_new_handle(&hc, &adc_) != ESP_OK) return log_e("Mic: adc_continuous_new_handle failed"), false;

    adc_digi_pattern_config_t pattern = {};
    pattern.atten = atten_;
    pattern.channel = channel_;
    pattern.unit = unit_;
    pattern.bit_width = SOC_ADC_DIGI_MAX_BITWIDTH;
    adc_continuous_config_t cfg = {};
    cfg.pattern_num = 1;
    cfg.adc_pattern = &pattern;
    cfg.sample_freq_hz = rate_;
    cfg.conv_mode = ADC_CONV_SINGLE_UNIT_1;
    cfg.format = ADC_DIGI_OUTPUT_FORMAT_TYPE2;
    if (adc_continuous_config(adc_, &cfg) != ESP_OK) return log_e("Mic: adc_continuous_config failed (rate %lu?)", static_cast<unsigned long>(rate_)), false;

    adc_continuous_evt_cbs_t cbs = {};
    cbs.on_pool_ovf = onOverflow;
    adc_continuous_register_event_callbacks(adc_, &cbs, this);

    // Calibration: each chip's ADC is measured at the factory and the result burnt into eFuse.
    // The "curve fitting" scheme turns raw values into millivolts with it.
    adc_cali_curve_fitting_config_t cc = {};
    cc.unit_id = unit_;
    cc.chan = channel_;
    cc.atten = atten_;
    cc.bitwidth = ADC_BITWIDTH_12;
    if (adc_cali_create_scheme_curve_fitting(&cc, &cali_) != ESP_OK) cali_ = nullptr;

    if (adc_continuous_start(adc_) != ESP_OK) return log_e("Mic: adc_continuous_start failed"), false;
    dcRate_ = 1.0f / 4096.0f;  // ~0.25 s to follow the bias at 16 kHz
    gain_ = 16.0f;             // 12-bit steps -> 16-bit
    log_i("Mic: KY-037 AO on GPIO %d (ADC1 channel %d) at %lu Hz, attenuation %s; DO on GPIO %d", PIN_MIC_AO, int(channel_),
          static_cast<unsigned long>(rate_), attenName(atten_), PIN_MIC_DO);
    return true;
  }

  void stopSource() {
    if (rx_) i2s_channel_disable(rx_), i2s_del_channel(rx_), rx_ = nullptr;
    if (adc_) adc_continuous_stop(adc_), adc_continuous_deinit(adc_), adc_ = nullptr;
    if (cali_) adc_cali_delete_scheme_curve_fitting(cali_), cali_ = nullptr;
  }

  static bool IRAM_ATTR onOverflow(adc_continuous_handle_t, const adc_continuous_evt_data_t *, void *self) {
    auto *mic = static_cast<Mic *>(self);
    mic->overruns_ = mic->overruns_ + 1;
    return false;
  }

  static void IRAM_ATTR onDoEdge(void *arg) {
    auto *self = static_cast<Mic *>(arg);
    self->doRises_ = self->doRises_ + 1;
    self->doLastRiseUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  static void task(void *arg) { static_cast<Mic *>(arg)->run(); }

  // One block of raw values from whichever source; 0 when nothing came.
  int readBlock(int32_t *out, int max) {
    if (source_ == Source::Inmp441) {
      size_t got = 0;
      if (!rx_ || i2s_channel_read(rx_, out, max * sizeof(int32_t), &got, 100) != ESP_OK) return 0;
      const int n = int(got / sizeof(int32_t));
      for (int i = 0; i < n; i++) out[i] >>= 8;  // 24 bits, sign kept
      return n;
    }
    uint32_t got = 0;
    if (!adc_ || adc_continuous_read(adc_, adcBuf_, sizeof(adcBuf_), &got, 100) != ESP_OK) return 0;
    int n = 0;
    for (uint32_t i = 0; i + SOC_ADC_DIGI_RESULT_BYTES <= got && n < max; i += SOC_ADC_DIGI_RESULT_BYTES) {
      const auto *d = reinterpret_cast<const adc_digi_output_data_t *>(&adcBuf_[i]);
      if (d->type2.channel == channel_) out[n++] = d->type2.data;
    }
    return n;
  }

  void run() {
    uint32_t windowStart = millis(), counted = 0;
    int low = INT32_MAX, high = INT32_MIN, lowHighCount = 0;
    float sumSq = 0;
    int peak = 0, inChunk = 0;
    bool primed = false;
    for (;;) {
      if (reconfigure_) {
        reconfigure_ = false;
        stopSource();
        rate_ = wantRate_;
        atten_ = wantAtten_;
        primed = false;
        if (!startSource()) log_e("Mic: could not restart");
      }
      const int n = readBlock(raw_, kBlock);
      if (n == 0) {
        if (!adc_ && !rx_) vTaskDelay(pdMS_TO_TICKS(100));
        continue;
      }
      uint32_t w = written_.load(std::memory_order_relaxed);
      for (int i = 0; i < n; i++) {
        const int raw = raw_[i];
        if (!primed) dc_ = raw, primed = true;
        dc_ += (raw - dc_) * dcRate_;
        low = raw < low ? raw : low;
        high = raw > high ? raw : high;
        float v = (raw - dc_) * gain_;
        v = v > 32767 ? 32767 : v < -32768 ? -32768 : v;
        const int16_t s = int16_t(v);
        ring_[w & kMask] = s;
        w++;
        sumSq += float(s) * s;
        const int a = s < 0 ? -s : s;
        peak = a > peak ? a : peak;
        if (++inChunk == kChunk) {
          const Frame f{w, sqrtf(sumSq / kChunk), int16_t(peak > 32767 ? 32767 : peak)};
          if (xQueueSend(frames_, &f, 0) != pdTRUE) dropped_ = dropped_ + 1;  // loop() fell 1 s behind
          sumSq = 0, peak = 0, inChunk = 0;
        }
        if (++lowHighCount >= int(rate_ / 10)) {
          rawLow_ = low;
          rawHigh_ = high;
          low = INT32_MAX, high = INT32_MIN, lowHighCount = 0;
        }
        counted++;
      }
      written_.store(w, std::memory_order_release);
      const uint32_t now = millis();
      if (now - windowStart >= 1000) measuredRate_ = counted * 1000 / (now - windowStart), counted = 0, windowStart = now;
    }
  }

  static constexpr int kBlock = 256;
  int16_t *ring_ = nullptr;
  QueueHandle_t frames_ = nullptr;
  TaskHandle_t task_ = nullptr;
  i2s_chan_handle_t rx_ = nullptr;
  adc_continuous_handle_t adc_ = nullptr;
  adc_cali_handle_t cali_ = nullptr;
  adc_unit_t unit_ = ADC_UNIT_1;
  adc_channel_t channel_ = ADC_CHANNEL_0;
  uint8_t adcBuf_[kBlock * SOC_ADC_DIGI_DATA_BYTES_PER_CONV];
  int32_t raw_[kBlock];
  Source source_ = Source::Ky037;
  uint32_t rate_ = 16000, wantRate_ = 16000;
  adc_atten_t atten_ = ADC_ATTEN_DB_12, wantAtten_ = ADC_ATTEN_DB_12;
  float dcRate_ = 1.0f / 4096.0f, gain_ = 16.0f;
  volatile bool reconfigure_ = false;
  std::atomic<uint32_t> written_{0};
  volatile float dc_ = 0;
  volatile int rawLow_ = 0, rawHigh_ = 0;
  volatile uint32_t overruns_ = 0, dropped_ = 0, measuredRate_ = 0;
  volatile uint32_t doRises_ = 0, doLastRiseUs_ = 0;
};

